INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CONST-001', NULL, 'الدستور اللبناني لعام 1926 مع التعديلات حتى عام 2004', NULL, 'Lebanese Constitution of 1926 with Amendments through 2004', '1926-05-23', 'Constitutional Law', 'Fundamental Law', 'active', 'Lebanon''s Constitution was originally promulgated under the French Mandate on May 23, 1926. It was significantly amended by the Taif Agreement (Document of National Accord) in 1989-1990, following the end of the 15-year civil war. The 1990 amendments restructured the distribution of political power among religious communities, transferred executive authority from the President to the Council of Ministers, and added the preamble affirming Lebanon''s commitment to international human rights instruments. The most recent amendments were made in 2004.', 54) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CP-001', NULL, 'قانون حماية المستهلك رقم 659/2005', NULL, 'Consumer Protection Law No. 659/2005', '2005-02-04', 'Commercial Law', 'Consumer Protection', 'active', 'Lebanon''s first comprehensive consumer protection statute, enacted February 4, 2005. Established the Consumer Protection Directorate at the Ministry of Economy and Trade. Covers consumer rights, labeling, advertising, contracts, guarantees, product safety, prohibited practices, and distance trading. Implements obligations consistent with EU consumer protection standards of the period.', 55) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-IP-001', NULL, 'قانون حماية الملكية الأدبية والفنية رقم 75/1999', NULL, 'Law on the Protection of Literary and Artistic Property No. 75/1999', '1999-04-03', 'Intellectual Property Law', 'Copyright', 'active', 'Lebanon''s principal copyright statute, enacted April 3, 1999 (Law No. 75). Replaced the Ottoman-era copyright provisions and aligned Lebanon with the Berne Convention and TRIPs Agreement requirements. Contains 101 articles covering definitions, protected works, copyright holders, economic and moral rights, exceptions and limitations, related rights (performers, producers, broadcasters, publishers), terms of protection, collective management associations, deposit requirements, and enforcement. Repealed Articles 137-180 of Resolution No. 2385/1924 and Articles 722-729 of the Penal Code.', 101) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-IP-002', NULL, 'قرار رقم 2385/1924 بشأن حقوق الملكية التجارية والصناعية (معدّل حتى 31 يناير 1946)', NULL, 'Resolution No. 2385/1924 on Commercial and Industrial Property Rights (amended through January 31, 1946)', '1924-01-17', 'Intellectual Property', 'Industrial Property, Trademarks, and Patents', 'active', 'Resolution No. 2385 was promulgated on January 17, 1924 during the French Mandate period, establishing Lebanon''s first comprehensive framework for commercial and industrial property rights including patents, industrial designs, and trademarks. It was subsequently amended multiple times, most notably by Resolution No. 84 of December 30, 1926, Resolution No. 170 of December 6, 1937, and the Law of January 31, 1946. The resolution established the Protection Bureau as the registration authority.', 23) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-PROC-001', NULL, 'قانون أصول المحاكمات الجزائية الجديد رقم 328/2001', NULL, 'New Code of Criminal Procedure (Law No. 328 of August 7, 2001 as amended by Act No. 359/2001)', '2001-08-07', 'Procedural Law', 'Criminal Procedure', 'active', 'Lebanon''s modern Code of Criminal Procedure enacted August 7, 2001 (Law No. 328), replacing the earlier 1948 code. Immediately amended by Act No. 359 of August 16, 2001. Introduces comprehensive rules for the Public Prosecution Service, Judicial Police, investigating judges, pretrial detention, trials, appeals, and cassation proceedings. Notable for strengthening suspect rights including the right to counsel, right to medical examination during detention, and limits on custody periods. Contains provisions for the Financial Prosecutor''s Office with specialized jurisdiction over banking, customs, and corporate offences.', 49) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-FIN-001', NULL, 'قانون السرية المصرفية الصادر بتاريخ 3 سبتمبر 1956 (المعدّل بموجب القانون رقم 306 تاريخ 28 أكتوبر 2022)', NULL, 'Law on Banking Secrecy of September 3, 1956 (as amended by Law 306 of October 28, 2022)', '1956-09-03', 'Financial Law', 'Banking Regulation', 'active', 'Lebanon''s Banking Secrecy Law of 1956 was one of the strictest in the world, positioning Lebanon as a regional banking hub. The law imposed an absolute duty of banking secrecy on all bank employees and prohibited seizure of deposits without client authorization. It was significantly amended in 2022 by Law 306, following the Lebanese financial crisis of 2019-2020, to lift banking secrecy for public officials, politically exposed persons, and in specific legal proceedings, as part of anti-corruption and anti-money laundering reforms.', 10) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-FIN-002', NULL, 'القانون رقم 44 تاريخ 24 نوفمبر 2015 المتعلق بمكافحة تبييض الأموال وتمويل الإرهاب', NULL, 'Law No. 44 of November 24, 2015 on Fighting Money Laundering and Terrorist Financing', '2015-11-24', 'Financial Law', 'Anti-Money Laundering', 'active', 'Lebanon''s Law No. 44 of 2015 replaced the earlier Law No. 318 of 2001 on Fighting Money Laundering. The 2015 law expanded predicate offences to include 21 categories of crimes (including tax evasion, environmental crimes, and human trafficking), created a broader framework for the Special Investigation Commission (SIC), and aligned Lebanon''s AML/CFT regime with FATF recommendations. The law requires all financial institutions, insurance companies, casinos, real estate dealers, and designated non-financial businesses to implement Customer Due Diligence and report suspicious transactions.', 12) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-DIGITAL-001', NULL, 'القانون رقم 81 تاريخ 10 أكتوبر 2018 المتعلق بالمعاملات الإلكترونية والبيانات الشخصية', NULL, 'Law No. 81 of October 10, 2018 Relating to Electronic Transactions and Personal Data', '2018-10-10', 'Digital and Technology Law', 'Electronic Commerce and Data Protection', 'active', 'Lebanon''s Electronic Transactions and Personal Data Law was enacted on October 10, 2018 (effective three months after publication). It was based on a draft law issued by Decree No. 9341 of November 17, 2012. The law establishes the legal framework for electronic writing and signatures, electronic commerce and contracts, electronic banking and financial services, electronic government, and personal data protection. It created COLIBAC (Lebanese Accreditation Council) as the body responsible for accrediting electronic authentication service providers.', 18) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CR-001', NULL, 'القانون رقم 65/2017 المتعلق بقمع التعذيب وغيره من ضروب المعاملة أو العقوبة القاسية أو اللاإنسانية أو المهينة', NULL, 'Law No. 65/2017 on the Punishment of Torture and Other Cruel, Inhuman or Degrading Treatment (Anti-Torture Law)', '2017-09-19', 'Criminal Law', 'Fundamental Rights and Human Rights', 'active', 'Law No. 65/2017 was adopted by the Lebanese Parliament on September 19, 2017, marking the first time that Lebanese legislation explicitly criminalized torture. Lebanon had ratified the UN Convention against Torture (CAT) in 2000 and its Optional Protocol (OPCAT) in 2008. The law amended Articles 401 and 185 of the Penal Code and Article 10 of the Code of Criminal Procedure. However, the law has been criticized by international human rights bodies for having an overly narrow definition of torture, setting a statute of limitations, imposing insufficiently grave penalties, and failing to explicitly require torture cases to be heard in civilian (rather than military) courts.', 6) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LABOR-001', NULL, 'قانون الضمان الاجتماعي (المرسوم الاشتراعي رقم 13955 تاريخ 26 سبتمبر 1963)', NULL, 'Social Security Law (Decree-Law No. 13955 of September 26, 1963)', '1963-09-26', 'Labor and Social Law', 'Social Security', 'active', 'Lebanon''s Social Security Law was promulgated by Decree-Law No. 13955 of September 26, 1963, establishing the National Social Security Fund (NSSF or CNSS in French). The law created a comprehensive social protection system covering four branches: sickness-maternity insurance, labor accidents and occupational diseases insurance, family allowances, and end-of-service indemnity. The Fund is governed by a Board of Directors with tripartite representation from the state, employers, and workers. The law has been amended numerous times, most significantly by Laws No. 9/74 (1974), 12/78 (1978), 15/69 (1969), and 27/88 (1988).', 6) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LABOR-002', NULL, 'قانون عقود العمل الجماعية والتوفيق والتحكيم (المرسوم الاشتراعي رقم 17386/1964)', NULL, 'Law on Collective Labor Contracts, Mediation and Arbitration (Decree-Law No. 17386/1964)', '1964-01-01', 'Labor and Social Law', 'Collective Labor Relations', 'active', 'Lebanon''s Collective Labor Contracts, Mediation and Arbitration Law was enacted by Decree-Law No. 17386 in 1964, providing the legal framework for collective bargaining alongside the individual employment framework under the 1946 Labour Law. The law establishes mechanisms for negotiating, registering, and enforcing collective employment contracts between trade unions and employers, and provides for mediation and arbitration as dispute resolution mechanisms for collective labor disputes.', 7) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-PROP-001', NULL, 'قوانين الإيجار: القانون رقم 159/1992 (الإيجارات الجديدة) والقانون رقم 160/1992 (الإيجارات القديمة) والقانون رقم 9/2014 (قانون الإيجار الجديد)', NULL, 'Rent Laws: Law No. 159/1992 (New Leases), Law No. 160/1992 (Old Leases), and Law No. 9/2014 (New Tenancy Law)', '1992-07-22', 'Property Law', 'Tenancy and Landlord-Tenant Relations', 'active', 'Post-civil war Lebanon enacted two complementary rent laws in July 1992. Law No. 159 of July 22, 1992 introduced ''freedom of contract'' for new leases (signed after July 22, 1992), replacing the previous mandatory renewal system. Law No. 160 of July 22, 1992 governed old leases (signed before July 23, 1992), providing a phased rent increase framework and limited landlord rights to reclaim property. Law No. 160 was extended 12 times over the following decades. In April 2014, the New Tenancy Law (Law 9/2014) was enacted to gradually liberalize all old rent contracts through a 9-year transition period with annual rent increases tied to property market values, supported by a rent assistance fund for vulnerable tenants.', 7) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-ADMIN-001', NULL, 'المرسوم الاشتراعي رقم 150/1983 في تنظيم القضاء العدلي (مشروع القانون المُعدِّل المُقدَّم إلى لجنة البندقية عام 2022)', NULL, 'Judicial Organization Decree-Law No. 150/1983 (Draft Amending Law as submitted to the Venice Commission in 2022)', '1983-09-16', 'Administrative Law', 'Judicial Organization', 'active', 'Decree-Law No. 150 of September 16, 1983 governs the organization of Lebanon''s ordinary courts (distinct from religious/personal status courts and the State Council for administrative courts). It establishes the structure of the court system, the composition and powers of the High Judicial Council (HJC), the appointment and discipline of judges, and related matters. The original decree has been criticized by international bodies including the ICJ and Venice Commission for allowing executive influence over judicial appointments and transfers. A draft law amending Decree-Law 150/83 was submitted to the Venice Commission in April 2022 and is reflected in the articles below.', 15) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-BANK-001', 'Law No. 1 of September 3, 1956 (Banking Secrecy)', 'قانون سرية المصارف - قانون رقم 1/1956', 'Loi No. 1/1956 - Secret Bancaire', 'Banking Secrecy Law', '1956-09-03', 'Banking & Financial', 'Banking Secrecy', 'amended', 'Inspired by the Swiss banking system, this law established Lebanon as a banking secrecy haven, attracting regional deposits and earning Lebanon the title ''Switzerland of the Middle East.'' Absolute secrecy binds bank managers and employees from disclosing client names, assets, and transactions to any authority. Code-numbered accounts permitted. The law has been progressively weakened since 2001 through anti-money laundering legislation and the 2022 partial lifting during the financial crisis. However, significant secrecy protections remain, making forensic investigations of the banking sector challenging.', 10) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-BANK-002', 'Code of Money and Credit (August 1, 1963)', 'قانون النقد والتسليف', 'Code de la Monnaie et du Crédit', 'Code of Money and Credit', '1963-08-01', 'Banking & Financial', 'Central Banking', 'amended', 'Established the Banque du Liban (BDL / مصرف لبنان) as Lebanon''s central bank and defined the monetary policy framework. Replaced the previously existing currency board arrangement. Defines BDL''s role in monetary stability, bank supervision, exchange rate policy, and lender of last resort functions. The Code became the subject of intense scrutiny during the post-2019 financial crisis, with debates about BDL''s financial engineering operations, loss allocation, and the need for fundamental reform of the monetary system.', 193) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-BANK-003', 'Law No. 44 of November 24, 2015 (Anti-Money Laundering)', 'قانون مكافحة تبييض الأموال وتمويل الإرهاب - قانون رقم 44/2015', 'Loi No. 44/2015 - Lutte contre le Blanchiment d''Argent et le Financement du Terrorisme', 'Law on Fighting Money Laundering and Terrorist Financing', '2015-11-24', 'Banking & Financial', 'Anti-Money Laundering', 'active', 'Replaced Law No. 318/2001 (which itself replaced initial AML provisions). Expanded the mandate of the Special Investigation Commission (SIC), broadened predicate offenses, enhanced know-your-customer requirements, and aligned Lebanon with FATF recommendations. The SIC has exclusive authority to decide on lifting banking secrecy for AML/CFT investigations.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-BANK-004', 'Law No. 42 of November 24, 2015 (Cross-Border Cash Transportation)', 'قانون التصريح عن نقل الأموال عبر الحدود - قانون رقم 42/2015', 'Loi No. 42/2015 - Déclaration du Transport Transfrontalier de Fonds', 'Law on Declaring Cross-Border Transportation of Money', '2015-11-24', 'Banking & Financial', 'Financial Controls', 'active', 'Requires declaration of cash above a threshold when entering or leaving Lebanon. Part of the 2015 package of financial reform laws addressing FATF requirements.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-BANK-005', 'Law No. 160 of August 17, 2011 (Insider Trading)', 'قانون تنظيم التداول بناء على معلومات غير معلنة - قانون رقم 160/2011', 'Loi No. 160/2011 - Délit d''Initié', 'Law Prohibiting Insider Trading', '2011-08-17', 'Banking & Financial', 'Securities Regulation', 'active', 'Prohibited insider trading using material non-public information. Part of efforts to develop Lebanon''s capital markets framework.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-BANK-006', 'Law No. 161 of August 17, 2011 (Financial Markets)', 'قانون الأسواق المالية - قانون رقم 161/2011', 'Loi No. 161/2011 - Marchés Financiers', 'Financial Markets Law / Capital Markets Law', '2011-08-17', 'Banking & Financial', 'Capital Markets', 'active', 'Established the Capital Markets Authority (CMA / هيئة الأسواق المالية) to regulate and supervise Lebanon''s financial markets. Governs the Beirut Stock Exchange (BSE), broker-dealer operations, and securities issuance.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-BANK-007', 'Decree No. 9976/1975 & Decree No. 29/1977 (Banking Free Zone)', 'المنطقة المصرفية الحرة', 'Zone Bancaire Libre', 'Banking Free Zone', '1975-01-01', 'Banking & Financial', 'Offshore Banking', 'amended', 'Established a banking free zone exempting non-resident foreign currency deposits from certain taxes and reserve requirements. Designed to attract offshore banking activity to Beirut.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-BANK-008', 'Law of December 19, 1961 (Joint Accounts)', 'قانون الحسابات المشتركة', 'Loi sur les Comptes Joints', 'Joint Bank Accounts Law', '1961-12-19', 'Banking & Financial', 'Banking Operations', 'active', 'Authorized banks to open joint accounts with single-signature operation. Important for banking convenience and asset planning.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-BANK-009', 'Law No. 306 of October 18, 2022 (Amendments to Banking Secrecy)', 'قانون رقم 306/2022 - تعديل قانون سرية المصارف', 'Loi No. 306/2022 - Modification de la Loi sur le Secret Bancaire', 'Amendment to Banking Secrecy Law (Partial Lifting)', '2022-10-18', 'Banking & Financial', 'Banking Secrecy Reform', 'active', 'Partially lifted banking secrecy for benefit of forensic audit of the Central Bank (BDL) and public institutions. A key reform demanded by the international community (IMF, World Bank, FATF) in the context of Lebanon''s financial crisis. Also lifted secrecy for tax authorities, anti-corruption bodies, and judicial investigations into public funds. Landmark legislation representing a significant shift in Lebanon''s banking secrecy tradition.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-BANK-010', 'Law No. 175 of May 29, 2020 (Capital Controls - attempted)', 'قانون الكابيتال كونترول', 'Loi sur le Contrôle des Capitaux', 'Capital Controls Law (Draft/Debated)', '2020-05-29', 'Banking & Financial', 'Capital Controls', 'active', 'In the context of Lebanon''s 2019 financial crisis, banks imposed de facto capital controls without legal basis. Multiple draft capital controls laws were debated in Parliament from 2020 onward. The absence of a formal capital controls law while banks restricted withdrawals was widely criticized as illegal and unconstitutional. Note: actual passage/status of this law requires verification as multiple versions were debated.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CASELAW-COMMERCIAL', NULL, 'اجتهادات قضائية - Commercial', NULL, 'Case Law Collection - Commercial', NULL, 'commercial', 'case_law', 'active', 'Collection of 57 judicial decisions and court rulings in Commercial law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CASELAW-LABOR', NULL, 'اجتهادات قضائية - Labor', NULL, 'Case Law Collection - Labor', NULL, 'labor', 'case_law', 'active', 'Collection of 1 judicial decisions and court rulings in Labor law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CASELAW-CIVIL', NULL, 'اجتهادات قضائية - Civil', NULL, 'Case Law Collection - Civil', NULL, 'civil', 'case_law', 'active', 'Collection of 2 judicial decisions and court rulings in Civil law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CASELAW-CRIMINAL', NULL, 'اجتهادات قضائية - Criminal', NULL, 'Case Law Collection - Criminal', NULL, 'criminal', 'case_law', 'active', 'Collection of 5 judicial decisions and court rulings in Criminal law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CASELAW-CONSTITUTIONAL', NULL, 'اجتهادات قضائية - Constitutional', NULL, 'Case Law Collection - Constitutional', NULL, 'constitutional', 'case_law', 'active', 'Collection of 4 judicial decisions and court rulings in Constitutional law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CASELAW-ADMINISTRATIVE', NULL, 'اجتهادات قضائية - Administrative', NULL, 'Case Law Collection - Administrative', NULL, 'administrative', 'case_law', 'active', 'Collection of 5 judicial decisions and court rulings in Administrative law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CASELAW-BANKING', NULL, 'اجتهادات قضائية - Banking', NULL, 'Case Law Collection - Banking', NULL, 'banking', 'case_law', 'active', 'Collection of 3 judicial decisions and court rulings in Banking law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CASELAW-FAMILY', NULL, 'اجتهادات قضائية - Family', NULL, 'Case Law Collection - Family', NULL, 'family', 'case_law', 'active', 'Collection of 2 judicial decisions and court rulings in Family law from Lebanese courts including the Court of Cassation, Courts of Appeal, Constitutional Council, Council of State, and specialized tribunals. These decisions establish important legal precedents in Lebanese jurisprudence.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CIV-001', 'Law of March 9, 1932 (Code of Obligations and Contracts)', 'قانون الموجبات والعقود الصادر بتاريخ 9 آذار 1932', 'Code des Obligations et des Contrats du 9 mars 1932', 'Code of Obligations and Contracts', '1932-03-09', 'Civil Law', 'General Civil Code', 'amended', 'Lebanon''s primary civil law code, adopted during the French Mandate. Modeled on the French Civil Code (Code Napoleon of 1804) and the Ottoman Mecelle, but adapted for Lebanese specificities. Known as the ''COC'' among Lebanese law students. Covers general obligations, contracts, torts, property transactions, and specific nominate contracts. Notably excludes personal status matters (marriage, divorce, inheritance) which are governed by each religious community''s own laws. The COC remains the backbone of Lebanese private law and is the most frequently cited code in Lebanese civil courts.', 1106) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CIV-002', 'Decree-Law No. 90 of September 16, 1983', 'قانون أصول المحاكمات المدنية - مرسوم اشتراعي رقم 90/83', 'Code de Procédure Civile - Décret-loi No. 90/1983', 'Code of Civil Procedure', '1983-09-16', 'Civil Law', 'Procedural Law', 'amended', 'Replaced the earlier Code of Civil Procedure. Issued as a decree-law during the Civil War period when Parliament was not functioning regularly. Governs all civil and commercial litigation procedures including jurisdiction, service of process, evidence, judgment, appeals, and execution. The arbitration chapter has gained particular importance for Lebanon''s role as a regional commercial center.', 876) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CIV-003', 'Law No. 3339 of November 12, 1930 (Property Law)', 'قانون الملكية العقارية - قرار رقم 3339', 'Arrêté No. 3339 - Propriété Foncière', 'Real Property Law', '1930-11-12', 'Civil Law', 'Property Law', 'amended', 'Established the modern Lebanese property registration system (Torrens system). Replaced Ottoman land law categories. Created the Land Registry system still in use today. Governs ownership, servitudes, usufruct, and real property rights.', 275) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CIV-004', 'Law of June 19, 1939 (Tenancy/Rent Law - Exceptional)', 'قانون الإيجارات', 'Loi sur les Loyers', 'Rent/Tenancy Law (Exceptional Provisions)', '1939-06-19', 'Civil Law', 'Tenancy/Rent', 'amended', 'Lebanon''s rent laws have been among the most politically contentious areas of legislation. Exceptional rent laws freezing rents for pre-1992 tenancies were enacted during and after the Civil War, creating a dual market between ''old rent'' (heavily protected tenants) and ''new rent'' (market-rate). The 2017 law attempted to gradually liberalize old rents over a transitional period but faced legal challenges and implementation difficulties.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CIV-005', 'Decree-Law No. 7855 of October 16, 1961 (Judicial Organization)', 'مرسوم اشتراعي رقم 7855 - التنظيم القضائي', 'Décret-loi No. 7855/1961 - Organisation Judiciaire', 'Judicial Organization Law', '1961-10-16', 'Judicial Organization', 'Court Structure', 'amended', 'Governs the structure and function of the Lebanese judiciary. Establishes the hierarchy of ordinary courts: courts of first instance, courts of appeal, and the Court of Cassation. Also establishes the Supreme Judicial Council headed by the First President (Chief Justice) of the Court of Cassation. Defines jurisdiction of civil, criminal, and commercial chambers at each level.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-COMM-001', 'Legislative Decree 304/1942', 'قانون التجارة اللبناني', 'Code de Commerce Libanais', 'Lebanese Commercial Code', '1942-12-24', 'Commercial Law', NULL, 'active', 'The Lebanese Commercial Code of 1942 was enacted during the French Mandate period, replacing Ottoman commercial laws. It was modeled after the French Commercial Code and established the foundation for modern commercial regulation in Lebanon. The Code covers trade acts, merchants, commercial companies, commercial papers (bills of exchange, cheques, promissory notes), and bankruptcy procedures.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-COMP-002', 'Legislative Decree 150/83', 'مرسوم تشريعي رقم 150/83 المتعلق بقانون الشركات التجارية', 'Décret Législatif n°150/83 relatif aux sociétés commerciales', 'Legislative Decree 150/83 on Commercial Companies', '1983-09-16', 'Commercial Law', NULL, 'active', 'Legislative Decree 150/83 was enacted to modernize company law in Lebanon, providing a comprehensive framework for commercial companies including LLCs (SARL), Joint Stock Companies (SA), and other company forms. It replaced earlier company regulations and aligned Lebanese company law with international standards.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-REG-004', 'Part of Legislative Decree 304/1942 and related decrees', 'أحكام السجل التجاري', 'Dispositions sur le Registre du Commerce', 'Commercial Register Provisions', '1942-12-24', 'Commercial Law', NULL, 'active', 'The Commercial Register provisions are contained within the Lebanese Commercial Code of 1942. The register serves as a public record of all commercial establishments operating in Lebanon, divided into a general register for traders and companies, and a special register for commercial establishments and contracts. Registration is maintained at each Court of First Instance.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-BANKR-005', 'Book V of Legislative Decree 304/1942 (Articles 459-668)', 'أحكام الإفلاس والتسوية القضائية', 'Dispositions sur la Faillite et le Règlement Judiciaire', 'Bankruptcy and Judicial Settlement Provisions', '1942-12-24', 'Commercial Law', NULL, 'active', 'Lebanon does not have a standalone Bankruptcy Law. Bankruptcy and insolvency are governed by Book V of the Commercial Code (Articles 459-668) and the Penal Code. The law provides for both voluntary and judicial liquidation, as well as debt restructuring options for distressed businesses. Workers may resort to the Labor Court and the National Social Security Fund to recover pay and benefits from bankrupt firms. The law criminalizes fraudulent bankruptcy.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-MAR-006', 'Maritime Commerce Law 1947 and Commercial Code provisions', 'قانون تجارة الملاحة البحرية', 'Code de Commerce Maritime', 'Maritime Commerce Law', '1947-01-01', 'Maritime Law', NULL, 'active', 'Lebanese maritime law is primarily regulated by the 1947 Maritime Commerce Law (Code de Commerce Maritime) and the Lebanese Commercial Code. Inspired by French maritime law, it contains detailed provisions on ship registration, maritime transport contracts, crew employment, maritime accidents, marine insurance, and arbitration procedures. Lebanon follows international standards including MLC 2006, STCW, SOLAS, and MARPOL conventions.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-AGENCY-007', 'Various provisions in Commercial Code and related decrees', 'أحكام الوكالة التجارية والتوزيع', 'Dispositions sur les Agents Commerciaux et la Distribution', 'Commercial Agency and Distribution Provisions', '1942-12-24', 'Commercial Law', NULL, 'active', 'Commercial agency in Lebanon is governed by provisions in the Commercial Code and Civil Code. The Ministry of Economy and Trade maintains statistics on exclusive agencies. Foreign companies operating through agents in Lebanon must comply with registration requirements. Agency agreements should clearly define the scope of authority, territory, and compensation terms.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CONS-008', 'Law 659/2005 and Law 81/2018 (E-Commerce provisions)', 'قانون حماية المستهلك', 'Loi sur la Protection du Consommateur', 'Consumer Protection Law', '2005-02-01', 'Consumer Protection', NULL, 'active', 'The Consumer Protection Law (659/2005) establishes protections for consumers in Lebanon, prohibiting unfair commercial practices. The law was updated by Law 81/2018 on Electronic Transactions to include e-commerce consumer protection provisions. The Ministry of Economy and Trade is responsible for enforcement and publishes monthly consumer protection reports.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-COMPET-009', 'Law 369/2001', 'قانون حماية المنافسة', 'Loi sur la Protection de la Concurrence', 'Competition Protection Law', '2001-01-01', 'Competition Law', NULL, 'active', 'Lebanon''s competition law is primarily governed by Law No. 369 of 2001 on the Protection of Competition. This law aims to promote and protect competition by prohibiting anti-competitive agreements, abuse of dominant positions, and other unfair market practices. Lebanon currently does not have a specialized competition authority; enforcement is mainly through the judiciary, where courts assess competition cases brought by the Ministry of Economy and Trade or private parties. Lebanon was the last country in the Middle East to introduce competition legislation (2022 according to some sources).', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-IP-010', 'Resolution 2385/1924 amended by Law 31/1/1946; Law 75/99; Law 240/2000', 'قوانين الملكية الفكرية والعلامات التجارية', 'Lois sur la Propriété Intellectuelle et les Marques de Commerce', 'Intellectual Property and Trademark Laws', '1924-01-17', 'Intellectual Property', NULL, 'active', 'Lebanon''s intellectual property framework is based on Resolution 2385 of 1924 (governing commercial and industrial property) which was amended by the Law of January 31, 1946. Copyright is protected under Law 75/99, and patents under Law 240/2000. Lebanon is compliant with TRIPS standards and has ratified the Paris Convention, Madrid Agreement, and Berne Convention. In 2024, Law 324 reduced trademark protection duration from 15 to 10 years for new registrations. The Ministry of Economy and Trade''s Intellectual Property Protection Office (IPPO) oversees IP matters.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-ETRAN-011', 'Law 81/2018', 'قانون المعاملات الإلكترونية والبيانات الشخصية', 'Loi relative aux Transactions Électroniques et aux Données Personnelles', 'Electronic Transactions and Personal Data Law', '2018-10-10', 'E-Commerce Law', NULL, 'active', 'Law 81/2018 was enacted to address the growing reliance on electronic documents, digital signatures, and online transactions. It provides a comprehensive legal framework for electronic transactions, personal data protection, and associated activities. The law grants electronic documents and signatures the same legal standing as traditional paper-based documents, facilitates e-commerce, and establishes data protection standards. COLIBAC (Lebanese Accreditation Council) oversees electronic authentication services.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-MONEY-012', 'Decree 13513/1963', 'قانون النقد والتسليف', 'Code de la Monnaie et du Crédit', 'Code of Money and Credit', '1963-01-08', 'Banking Law', NULL, 'active', 'The Code of Money and Credit is the main regulation of the banking and financial system in Lebanon. It covers the regulation of money, the Central Bank of Lebanon''s role and functions, banks'' activities, and the activities of professions linked to the banking profession. Law 28/67 amended the Code and established the Higher Banking Commission and the Banking Control Commission at the Central Bank.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-AML-013', 'Law 318/2001 amended by Law 44/2015', 'قانون مكافحة تبيض الأموال', 'Loi sur la Lutte contre le Blanchiment d''Argent', 'Anti-Money Laundering Law', '2001-04-20', 'Financial Crime Law', NULL, 'active', 'Law 318/2001 was enacted to combat money laundering and terrorist financing in Lebanon. It established the Special Investigation Commission (SIC) as the sole authority empowered to lift banking secrecy for investigations related to money laundering and terrorist financing. The law was amended by Law 44/2015 to strengthen provisions.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-COM-001', 'Legislative Decree of December 24, 1942 (Code of Commerce)', 'قانون التجارة البرية الصادر بتاريخ 24 كانون الأول 1942', 'Code de Commerce Terrestre du 24 décembre 1942', 'Code of Terrestrial Commerce / Code of Commerce', '1942-12-24', 'Commercial Law', 'General Commercial Code', 'amended', 'Lebanon''s commercial code was modeled closely on the French Commercial Code. Replaced the Ottoman Commercial Code (1850), itself a translation of the French Code de Commerce of 1807. Governs commercial transactions, merchant obligations, partnerships, negotiable instruments, bankruptcy, and commercial pledges. The companies chapter was replaced by Decree-Law 150/1983.', 734) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-COM-002', 'Decree-Law No. 150 of September 16, 1983', 'مرسوم اشتراعي رقم 150 - قانون الشركات التجارية', 'Décret-loi No. 150/1983 - Sociétés Commerciales', 'Companies / Commercial Companies Law', '1983-09-16', 'Commercial Law', 'Companies', 'amended', 'Replaced the companies portion of the 1942 Code of Commerce. Governs formation, operation, and dissolution of all types of commercial companies: general partnerships (société en nom collectif), limited partnerships (société en commandite simple), joint stock companies (société anonyme / SAL), limited liability companies (société à responsabilité limitée / SARL), and holding companies (société holding). The SAL and SARL are the most common corporate forms in Lebanon.', 262) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-COM-003', 'Legislative Decree of September 24, 1947 (Maritime Commerce)', 'قانون التجارة البحرية', 'Code de Commerce Maritime', 'Maritime Commerce Code', '1947-09-24', 'Commercial Law', 'Maritime Law', 'amended', 'Governs maritime commerce including ship registration, maritime liens, charter parties, bills of lading, maritime insurance, collisions, salvage, and general average. Important for Lebanon given the significance of the Port of Beirut to the national economy.', 340) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-COM-004', 'Law No. 75 of April 3, 1967 (Intellectual Property / Copyright)', 'قانون حماية الملكية الأدبية والفنية - قانون رقم 75/1967', 'Loi No. 75/1967 sur la Protection de la Propriété Littéraire et Artistique', 'Literary and Artistic Property Protection Law', '1967-04-03', 'Commercial Law', 'Intellectual Property', 'amended', 'Lebanon''s primary intellectual property legislation. Covers copyright, literary and artistic works, and neighboring rights. Lebanon is a member of the Berne Convention and TRIPS Agreement. Trademark protection is governed by separate legislation (Decree No. 2385 of 1924).', 97) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-COM-005', 'Law of December 4, 1967 (Consumer Protection - initial)', 'قانون حماية المستهلك', 'Loi sur la Protection du Consommateur', 'Consumer Protection Law', '2005-02-04', 'Commercial Law', 'Consumer Protection', 'active', 'Law No. 659/2005 established the consumer protection framework including product safety requirements, labeling, fair pricing, and established the Consumer Protection Directorate within the Ministry of Economy and Trade.', 74) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-COM-006', 'Law No. 2/1967 (Trade Marks and Unfair Competition)', 'قانون العلامات الفارقة', 'Arrêté No. 2385/1924 et lois subséquentes - Marques de fabrique et de commerce', 'Trademarks, Trade Names and Unfair Competition', '1924-01-17', 'Commercial Law', 'Intellectual Property / Trademarks', 'amended', 'Originally enacted as Decree No. 2385 of January 17, 1924, during the French Mandate. One of the oldest continuously enforced laws in Lebanon. Governs trademark registration, protection, and enforcement. Lebanon maintains a first-to-use system rather than first-to-file.', 106) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-COM-001-EXPANDED', 'Legislative Decree No. 304 of December 24, 1942', 'قانون التجارة', 'Code de Commerce', 'Commercial Code (Expanded)', '1942-12-24', 'Commercial Law', 'General Commercial Code', 'amended', 'Full article-level text of the Lebanese Commercial Code (Legislative Decree No. 304/1942). Covers trade, merchants, commercial companies (partnerships, joint stock, limited liability), negotiable instruments, bankruptcy and insolvency, maritime commerce, and commercial agency.', 725) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CONST-012', 'National Pact of 1943 (الميثاق الوطني)', 'الميثاق الوطني اللبناني 1943', 'Pacte National de 1943', 'Lebanese National Pact of 1943', '1943-10-07', 'Constitutional Law', 'Foundational Agreement', 'active', 'An unwritten verbal agreement between President Bechara el-Khoury (Maronite Christian) and Prime Minister Riad al-Solh (Sunni Muslim) in 1943. Formalized through al-Solh''s ministerial declaration to the Chamber of Deputies on October 7, 1943. Key provisions: (1) Muslims would not seek unity with Syria, (2) Christians would relinquish French protection, (3) Lebanon would have an ''Arab face'', (4) Key political positions distributed by confession: President = Maronite, PM = Sunni, Speaker = Shia. The Pact established the confessional power-sharing that defines Lebanese governance. It has no formal legal text but carries constitutional weight through custom and practice. The 6:5 Christian-to-Muslim ratio in Parliament was also formalized around this period (though technically from a July 1943 French High Commissioner decision). The Taif Agreement of 1989 modified but did not replace the National Pact''s core principles.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CONST-013', 'Taif Agreement / Document of National Accord (1989)', 'وثيقة الوفاق الوطني - اتفاق الطائف', 'Accord de Taëf / Charte de Réconciliation Nationale Libanaise', 'Taif Agreement / Charter of Lebanese National Reconciliation', '1989-10-22', 'Constitutional Law', 'National Reconciliation', 'active', 'Signed on October 22, 1989, in Taif, Saudi Arabia, by 62 of the 73 surviving Lebanese Members of Parliament to end the 15-year Lebanese Civil War (1975-1990). Approved by Parliament on November 5, 1989, and implemented through constitutional amendments ratified on August 21, 1990, signed into law on September 21, 1990. Key reforms: (1) Equalized confessional representation in Parliament from 6:5 Christian/Muslim to 1:1, expanding to 108 then 128 seats; (2) Transferred significant executive power from President to Council of Ministers; (3) Enhanced role of Prime Minister and Speaker; (4) Established Constitutional Council; (5) Called for eventual abolition of political confessionalism (never implemented); (6) Called for administrative decentralization; (7) Disbanded militias (partially implemented); (8) Affirmed Lebanese sovereignty. Brokered by Saudi Arabia with backing from the Arab League and international community.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CRIM-002-EXPANDED', 'Law No. 328 of August 7, 2001', 'قانون أصول المحاكمات الجزائية', 'Code de Procédure Pénale', 'Code of Criminal Procedure (Expanded)', '2001-08-07', 'Criminal Law', 'Criminal Procedure', 'amended', 'Full article-level text of the Lebanese Code of Criminal Procedure (Law No. 328/2001). Governs criminal investigations, prosecution, trial procedures, evidence, detention, appeals, and execution of criminal judgments.', 420) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LAB-001-EXPANDED', NULL, 'قانون العمل', NULL, 'Code of Labour (1946) - Expanded', '1946-09-23', 'labor', 'employment', NULL, 'The Lebanese Code of Labour was enacted on 23 September 1946, shortly after Lebanon''s independence. It remains the primary legislation governing employment relationships in Lebanon, covering individual and collective labor relations, working conditions, wages, termination, and labor disputes. Major amendments have been introduced over the decades, but the core framework remains in force.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-LAB-001', 'Law 1/1946', 'قانون العمل اللبناني', 'Code du Travail Libanais', 'Lebanese Labour Code', '1946-09-23', 'Labor Law', NULL, 'active', 'Enacted on September 23, 1946, shortly after Lebanese independence. Based on French labor law traditions. Has undergone numerous amendments to adapt to changing economic and social conditions. The 2010 amendment (Law 129/2010) was significant for Palestinian refugee workers.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-SOC-001', 'Law 13955/1963', 'قانون الضمان الاجتماعي', 'Loi sur la Sécurité Sociale', 'Social Security Law', '1963-09-26', 'Social Security', NULL, 'active', 'Established the National Social Security Fund (CNSS/NSSF) in 1963. Created a social insurance system covering family allowances, sickness and maternity, and end-of-service indemnity. Major reform in December 2023 with Law 319 introducing a pension system to replace the end-of-service indemnity.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-MIN-001', 'Law 36/67', 'قانون تحديد الحد الأدنى للأجور', 'Loi sur la fixation du salaire minimum', 'Law Concerning Minimum Wage Fixing', '1967-05-16', 'Labor Law', NULL, 'active', 'Established the legal framework for minimum wage setting in Lebanon. Created the tripartite Price Index Committee (workers, employers, government) to advise on wage adjustments based on cost of living.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-MIN-002', 'Decree 7426/2012', 'مرسوم تحديد الحد الأدنى للأجور وتقديم علاوة غلاء المعيشة', 'Décret fixant le salaire minimum et accordant une allocation de vie chère', 'Decree Fixing Minimum Wage and Providing Cost of Living Allowance', '2012-01-25', 'Labor Law', NULL, 'amended', 'Major minimum wage increase from LBP 500,000 to LBP 675,000 monthly. Implemented after extensive negotiations and resignation of Minister of Labor Charbel Nahas who opposed the transportation allowance decree.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-MIN-003', 'Decree 10598/2022', 'مرسوم زيادة الحد الأدنى للأجور لتغطية غلاء المعيشة', 'Décret d''augmentation du salaire minimum pour couvrir le coût de la vie', 'Decree Increasing Minimum Wage for Cost of Living Coverage', '2022-10-01', 'Labor Law', NULL, 'amended', 'First major adjustment during economic crisis. Increased minimum wage from LBP 675,000 to LBP 1,275,000 monthly. Response to currency devaluation and hyperinflation.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-MIN-004', 'Decree 9129/2022', 'مرسوم تعديل المرسوم 7426/2012 بشأن الحد الأدنى للرواتب الشهرية', 'Décret modifiant le Décret 7426/2012 concernant le salaire minimum mensuel', 'Decree Amending Decree 7426/2012 on Minimum Monthly Wages', '2022-07-01', 'Labor Law', NULL, 'amended', 'Major wage adjustment during economic crisis. New minimum wage set at LBP 2,000,000 monthly. Also increased NSSF ceilings for sickness/maternity and family allowances.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-MIN-005', 'Decree 13164/2024', 'مرسوم رفع الحد الأدنى للأجور', 'Décret d''augmentation du salaire minimum', 'Decree Raising Minimum Wage', '2024-04-05', 'Labor Law', NULL, 'amended', 'Further adjustment during ongoing economic crisis. Minimum wage increased to LBP 18 million monthly, effective April 1, 2024.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-MIN-006', 'Decree 699/2025', 'مرسوم تحديد الحد الأدنى للرواتب الشهرية واليومية', 'Décret fixant les salaires minimums mensuels et journaliers', 'Decree Fixing Minimum Monthly and Daily Wages', '2025-08-01', 'Labor Law', NULL, 'active', 'Latest minimum wage update as of August 2025. Minimum wage raised to LBP 28 million monthly (approximately $310 at market rate). NSSF maximum salary ceiling increased to LBP 140 million for maternity/sickness.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-PEN-001', 'Law 319/2023', 'قانون إصلاح الضمان الاجتماعي وإنشاء نظام التقاعد', 'Loi de réforme de la sécurité sociale et création du régime de retraite', 'Law on Social Security Reform and Pension System Creation', '2023-12-28', 'Social Security', NULL, 'active', 'Landmark reform passed after 20+ years of discussions. Replaces the end-of-service indemnity (EOSI) lump-sum system with a lifelong pension based on notional defined contribution (NDC). Addresses the severe underfunding of the previous system and provides old-age income security. Approximately 80% of elderly Lebanese were not receiving any pension before this reform.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-PAL-001', 'Law 128/2010', 'قانون تعديل المادة 9 من قانون الضمان الاجتماعي بشأن اللاجئين الفلسطينيين', 'Loi modifiant l''article 9 de la loi sur la sécurité sociale concernant les réfugiés palestiniens', 'Law Amending Article 9 of Social Security Law Regarding Palestinian Refugees', '2010-08-17', 'Social Security', NULL, 'active', 'Adopted alongside Law 129/2010 amending Labor Code Article 59. First legal recognition of Palestinian refugees in Lebanese legislation. However, excludes them from health, maternity, and family benefits. Contributions (23.5%) same as Lebanese workers but only 8.5% goes to their end-of-service account.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-PAL-002', 'Law 129/2010', 'قانون تعديل المادة 59 من قانون العمل بشأن اللاجئين الفلسطينيين', 'Loi modifiant l''article 59 du Code du travail concernant les réfugiés palestiniens', 'Law Amending Article 59 of Labour Code Regarding Palestinian Refugees', '2010-08-24', 'Labor Law', NULL, 'active', 'Historic amendment recognizing Palestinian refugees in Lebanese labor law. Exempts them from work permit fees and reciprocity principle. However, they still need work permits and are barred from liberal professions requiring syndicate membership (medicine, law, engineering, etc.).', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-PUB-001', 'Decree-Law 112/1959', 'مرسوم بقانون نظام موظفي الإدارة العامة', 'Décret-loi réglementant les fonctionnaires de l''administration publique', 'Decree-Law on Civil Servants Regulation', '1959', 'Labor Law', NULL, 'active', 'Primary legislation governing public sector employment in Lebanon. Establishes the civil service framework, salary scales, promotion criteria, and retirement system for government employees.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-PUB-002', 'Law 46/2017', 'قانون سلسلة الرتب والرواتب في القطاع العام', 'Loi sur l''échelle des grades et salaires dans le secteur public', 'Law on Public Sector Salary Scale', '2017-08-21', 'Labor Law', NULL, 'active', 'Major reform of public sector salaries after years of stagnation. Unified salary scale across government sectors. Set minimum wage at LBP 675,000 matching private sector. Significant increases for teachers and military personnel.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-ILO-001', 'Legislative Decree 70/1977', 'مرسوم تشريعي رقم 70/1977 - المصادقة على اتفاقية العمل الدولية رقم 131', 'Décret législatif 70/1977 - ratification Convention OIT n° 131', 'Legislative Decree 70/1977 - Ratification of ILO Convention 131', '1977-06-25', 'Labor Law', NULL, 'active', 'Ratified ILO Convention 131 on Minimum Wage Fixing, establishing international standards for minimum wage determination through tripartite consultation.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-ARB-001', 'Law 183/2000', 'قانون رقم 183/2000 - المصادقة على الاتفاقية العربية رقم 15', 'Loi 183/2000 - ratification Convention arabe n° 15', 'Law 183/2000 - Ratification of Arab Convention 15', '2000-05-24', 'Labor Law', NULL, 'active', 'Ratified Arab Labor Convention 15 (1983) on wage determination and protection. References Article 7 on employee''s right to full salary even when not performing work for reasons beyond their control.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-ALL-001', 'Decree 964/2025', 'مرسوم تحديد بدل المدرسة للعام الدراسي 2024-2025', 'Décret fixant l''allocation scolaire pour l''année 2024-2025', 'Decree on Schooling Allowance for Academic Year 2024-2025', '2025-09-04', 'Labor Law', NULL, 'active', 'Annual decree setting schooling allowances for employees'' children. Separate rates for public and private education.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-NSS-002', 'Decree 887/2025', 'مرسوم تعديل المادة 68 من قانون الضمان الاجتماعي - زيادة الحد الأقصى للأمومة والمرض', 'Décret modifiant article 68 loi sécurité sociale - augmentation plafond maternité/maladie', 'Decree Amending Article 68 of Social Security Law - Maternity/Sickness Ceiling Increase', '2025-08-21', 'Social Security', NULL, 'active', 'Increased NSSF ceiling for maternity and sickness contributions from LBP 90 million to LBP 120 million monthly.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-NSS-003', 'Decree 422/2025', 'مرسوم تعديل التعويضات العائلية للضمان الاجتماعي', 'Décret modifiant les allocations familiales de sécurité sociale', 'Decree Amending Social Security Family Allowances', '2025-06-19', 'Social Security', NULL, 'active', 'Significant increase in family allowances. Also raised the contribution ceiling from LBP 12 million to LBP 18 million.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-NSS-004', 'Decree 12773/2023', 'مرسوم تعديل الحد الأقصى للراتح الخاضع للضمان الاجتماعي - التعويضات العائلية', 'Décret modifiant le plafond des rémunérations soumises à sécurité sociale - allocations familiales', 'Decree Amending NSSF Ceiling - Family Allowances', '2023-12-28', 'Social Security', NULL, 'amended', 'First major increase in NSSF family allowance ceiling in years. Raised from LBP 2.825 million to LBP 12 million.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TRA-001', 'Law 164/2011', 'قانون مكافحة الاتجار بالأشخاص', 'Loi de lutte contre la traite des personnes', 'Anti-Trafficking Law', '2011', 'Labor Law', NULL, 'active', 'Lebanon''s primary anti-trafficking legislation. Addresses forced labor and sex trafficking. Important for protecting migrant workers under the kafala system.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-FOR-001', 'Decree 4186/2010', 'مرسوم تعديل المرسوم 10188/1962 المتعلق بدخول الأجانب إلى لبنان وإقامتهم ومغادرتهم', 'Décret modifiant le Décret 10188/1962 sur entrée, séjour et sortie des étrangers', 'Decree Amending Decree 10188/1962 on Foreigners Entry, Stay and Exit', '2010', 'Labor Law', NULL, 'active', 'Amended the 1962 law on foreign entry and stay. Part of the legal framework governing foreign workers in Lebanon.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-FOR-002', 'By-Law 17561/1964', 'نظام 17561/1964 المنظم لعمل الأجانب في لبنان', 'Règlement 17561/1964 réglementant le travail des étrangers au Liban', 'By-Law 17561/1964 Regulating Work of Foreigners in Lebanon', '1964', 'Labor Law', NULL, 'active', 'Primary regulation governing foreign worker permits in Lebanon. Requires 3 Lebanese workers per foreign worker (not always strictly enforced).', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-FOR-003', 'Decision 1/41/2017', 'قرار وزير العمل رقم 1/41 لسنة 2017 بشأن المهن المحصورة باللبنانيين', 'Décision ministre du travail 1/41/2017 sur professions réservées aux Libanais', 'Minister of Labor Decision 1/41/2017 on Occupations Reserved for Lebanese Nationals', '2017', 'Labor Law', NULL, 'active', 'Annual list of occupations reserved for Lebanese nationals. Updated yearly by Ministry of Labor. Foreigners can be granted permits for these positions only if their specialization is not available locally.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-OPT-001', 'Law 248/2000', 'قانون رقم 248/2000 - الضمان الاجتماعي الاختياري', 'Loi 248/2000 - Sécurité sociale facultative', 'Law 248/2000 - Optional Social Security', '2000-09-09', 'Social Security', NULL, 'active', 'Created optional social security coverage for those not covered by mandatory scheme, particularly elderly. Implementation started in 2002 with Decree 7352 but has faced operational challenges.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-RET-001', 'Law 27/2017', 'قانون رقم 27/2017 - السماح للمتقاعدين بالانتفاع من فروع المرض والأمومة', 'Loi 27/2017 - Permettre aux retraités de bénéficier des branches maladie/maternité', 'Law 27/2017 - Allowing Retirees to Benefit from Sickness and Maternity Branches', '2017-02-10', 'Social Security', NULL, 'active', 'Important expansion of NSSF coverage allowing retirees to access healthcare. However, requires 20 years of actual enrollment, excluding many contract workers.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TRA-002', 'Decree 8740/2022', 'مرسوم زيادة بدل النقل للموظفين', 'Décret augmentant l''allocation de transport', 'Decree Increasing Transportation Allowance', '2022-02-03', 'Labor Law', NULL, 'amended', 'Increased daily transportation allowance from LBP 24,000 to LBP 65,000 during economic crisis.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TRA-003', 'Decree 9849/2022', 'مرسوم تعديل بدل النقل', 'Décret modifiant l''allocation de transport', 'Decree Amending Transportation Allowance', '2022-08-18', 'Labor Law', NULL, 'active', 'Further increase to transportation allowance from LBP 65,000 to LBP 95,000.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-WOR-001', 'Law 1943 (Work Injury)', 'قانون إصابات العمل 1943', 'Loi sur les accidents du travail 1943', 'Work Injury Law 1943', '1943', 'Labor Law', NULL, 'active', 'Pre-dates Labor Code 1946. Employer-liability system for work injuries. Provides temporary and permanent disability benefits. Administered through NSSF which contracts with hospitals for medical care.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-FAM-001', 'Decree 1965 (Family Allowances)', 'مرسوم التعويضات العائلية 1965', 'Décret allocations familiales 1965', 'Family Allowances Decree 1965', '1965', 'Social Security', NULL, 'active', 'Implemented family allowances system under Social Security Law. Originally provided LBP 60,000 for wife and LBP 33,000 per child (max 5). Significantly increased in 2025 to LBP 1.2 million for spouse and LBP 660,000 per child.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-JUD-001', 'Law 173/2011', 'قانون رقم 173/2011 - رفع رواتب القضاة', 'Loi 173/2011 - augmentation salaires juges', 'Law 173/2011 - Raising Judges'' Salaries', '2011', 'Labor Law', NULL, 'active', 'Updated salary scale for judges. Highest judicial salary was approximately $6,233 before currency collapse, now worth about $995.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-EDU-001', 'Law 206/2012', 'قانون رقم 206/2012 - رفع رواتب أساتذة الجامعة اللبنانية', 'Loi 206/2012 - augmentation salaires professeurs Université libanaise', 'Law 206/2012 - Raising Lebanese University Professors'' Salaries', '2012', 'Labor Law', NULL, 'active', 'Updated salary scale for Lebanese University professors. Highest professor salary was approximately $5,617 before currency collapse, now worth about $896.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LAB-001', 'Law of September 23, 1946 (Labor Code)', 'قانون العمل اللبناني الصادر في 23 أيلول 1946', 'Code du Travail du 23 septembre 1946', 'Labor Code / Labour Law', '1946-09-23', 'Labor & Social Security', 'General Labor Code', 'amended', 'Enacted after twenty years of intense workers'' mobilizations in tobacco, typography, transport, petroleum, and port sectors. Governs private and mixed sector employment. Public sector regulated by separate Decree-Law 112/1959. Notable exclusions historically included domestic workers, agricultural workers, and family businesses. Domestic workers were partially covered by Law No. 41/2024. The Labor Code requires prior authorization from the Ministry of Labour for trade union formation, which has been criticized by ILO committees. Lebanon has ratified most core ILO conventions.', 113) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LAB-002', 'Decree No. 13955 of September 26, 1963 (Social Security)', 'المرسوم رقم 13955 - قانون الضمان الاجتماعي', 'Décret No. 13955/1963 - Sécurité Sociale', 'Social Security Act / National Social Security Fund (NSSF) Law', '1963-09-26', 'Labor & Social Security', 'Social Security', 'amended', 'Established Lebanon''s social security system through the National Social Security Fund (NSSF). Originally planned to have four branches, but only three have been fully implemented: Sickness and Maternity, Family Allowances, and End of Service Indemnity. A retirement/pension branch has never been implemented despite decades of discussion. The NSSF covers employees registered in the private sector. Self-employed persons and informal workers largely remain excluded. The fund has faced severe financial difficulties, particularly since the 2019 economic crisis.', 88) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LAB-003', 'Decree-Law No. 112 of June 12, 1959 (Civil Servants)', 'مرسوم اشتراعي رقم 112/59 - نظام الموظفين', 'Décret-loi No. 112/1959 - Statut des Fonctionnaires', 'Civil Servants Regulation / Public Employment Law', '1959-06-12', 'Labor & Social Security', 'Public Employment', 'amended', 'Governs employment of civil servants in the public sector. Separate from the Labor Code which covers private sector. Establishes rights, obligations, disciplinary procedures, and career paths for government employees. Confessional balance requirements apply to public sector appointments under the Constitution.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LAB-004', 'Decree-Law No. 115 of June 12, 1959', 'مرسوم اشتراعي رقم 115/59 - إنشاء التفتيش المركزي', 'Décret-loi No. 115/1959 - Inspection Centrale', 'Central Investigation/Inspection Office Law', '1959-06-12', 'Labor & Social Security', 'Public Administration', 'active', 'Established the Central Investigation Office (التفتيش المركزي), an oversight body for public administration. Exercises supervisory control over government ministries and agencies.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LAB-005', 'Decree-Law No. 136 of September 16, 1983', 'مرسوم اشتراعي رقم 136/83 - نظام حوادث العمل', 'Décret-loi No. 136/1983 - Accidents du Travail', 'Work Accidents Law / Occupational Injuries', '1983-09-16', 'Labor & Social Security', 'Occupational Safety', 'active', 'Regulates work-related accidents and occupational injuries. Applies to both Lebanese and foreign employees. Establishes employer liability for workplace accidents and occupational diseases.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LAB-006', 'Decree No. 3572/1980 (Arbitration Labour Councils)', 'مرسوم رقم 3572/1980 - صلاحيات مجالس العمل التحكيمية', 'Décret No. 3572/1980 - Conseils du Travail Arbitraux', 'Decree on the Authorities of Arbitration Labour Councils', '1980-09-01', 'Labor & Social Security', 'Labor Dispute Resolution', 'active', 'Establishes the labor arbitration council system for resolving labor disputes. Each council consists of a judge (presiding), a workers'' representative, and an employers'' representative. Decisions can be challenged by objection, third-party objection, and cassation.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LAB-007', 'Decree No. 17561 of September 18, 1964 (Foreign Workers)', 'مرسوم رقم 17561/1964 - تنظيم عمل الأجانب', 'Décret No. 17561/1964 - Réglementation du Travail des Étrangers', 'Foreign Workers Regulation', '1964-09-18', 'Labor & Social Security', 'Foreign Workers', 'amended', 'Regulates employment of foreign nationals in Lebanon. Requires work permits and residency permits for legal employment. Sets out permit categories and restrictions by profession. Frequently discussed in the context of Syrian and Palestinian workers in Lebanon.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LAB-008', 'Decree No. 11802 of January 30, 2004 (Occupational Safety & Hygiene)', 'مرسوم رقم 11802/2004 - تنظيم الوقاية والسلامة والصحة المهنية', 'Décret No. 11802/2004 - Prévention, Sécurité et Hygiène Professionnelle', 'Occupational Prevention, Safety and Hygiene Regulation', '2004-01-30', 'Labor & Social Security', 'Occupational Safety', 'active', 'Comprehensive occupational safety and health regulation implementing the Labor Code. Establishes prevention and safety requirements for all establishments subject to the Labor Code.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1920-318', 'Decree 318/1920', 'مرسوم إعلان قيام دولة لبنان الكبير', 'Décret n° 318 proclamant l''établissement de l''État du Grand Liban', 'Decree No. 318 Proclaiming the Establishment of the State of Greater Lebanon', '1920-08-31', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - High Commissioner General Henri Gouraud issued this decree one day before the public proclamation of Greater Lebanon on September 1, 1920', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1920-336', 'Decree 336/1920', 'النظام الأساسي المؤقت لدولة لبنان الكبير', 'Décret n° 336 portant règlement provisoire de l''État du Grand Liban', 'Decree No. 336 on the Interim Bylaws of the State of Greater Lebanon', '1920-09-01', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - High Commissioner General Gouraud issued this decree the day after the proclamation of Greater Lebanon, establishing the administrative structure', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1920-086', 'Decree 86/1920', 'مرسوم إنشاء مديرية العدلية', 'Décret n° 86 créant la Direction de la Justice', 'Decree No. 86 Establishing the Directorate of Justice', '1920-10-29', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - Governor Major Trabaud issued this decree establishing the Directorate of Justice as the core agency of what would become the Ministry of Justice', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1920-343', 'Decree 343/1920', 'مرسوم تعيين شارل دباس أول مدير للعدلية', 'Décret n° 343 nommant Charles Débbas premier Directeur de la Justice', 'Decree No. 343 Appointing Charles Débbas as First Director of Justice', '1920-09-01', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - High Commissioner General Gouraud appointed Charles Débbas, who later became the first President of Lebanon in 1926', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1920-589', 'Decree 589/1920', 'مرسوم تحويل مديرية العدلية إلى مصلحة العدلية', 'Décret n° 589 transformant la Direction de la Justice en Service de la Justice', 'Decree No. 589 Transforming the Directorate of Justice into the Department of Justice', '1920-12-20', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - High Commissioner Robert de Caix issued this decree changing the name from Directorate to Department', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1920-601', 'Decree 601/1920', 'مرسوم إنشاء مكتب العدلية', 'Décret n° 601 créant le Bureau de la Justice', 'Decree No. 601 Establishing the Bureau of Justice', '1920-12-30', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - High Commissioner Robert de Caix issued this decree establishing the Bureau of Justice', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1922-1647', 'Decree 1647/1922', 'مرسوم إنشاء اللجنة الاستشارية للتشريع', 'Décret n° 1647 créant le Comité consultatif de Législation', 'Decree No. 1647 Establishing the Consultative Committee of Legislation', '1922-12-17', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - Governor Trabaud issued this decree establishing the first legislative drafting committee in Lebanon', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1923-1614', 'Decree 1614/1923', 'مرسوم تعيين أعضاء اللجنة الاستشارية للتشريع', 'Décret n° 1614 nommant les membres du Comité consultatif de Législation', 'Decree No. 1614 Appointing Members of the Consultative Committee of Legislation', '1923-04-10', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - Governor Trabaud appointed the first members of the Consultative Committee of Legislation', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1923-1787', 'Decree 1787/1923', 'مرسوم تعديل تكوين اللجنة الاستشارية للتشريع', 'Décret n° 1787 modifiant la composition du Comité consultatif de Législation', 'Decree No. 1787 Amending the Composition of the Consultative Committee of Legislation', '1923-03-02', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - Governor Trabaud amended the composition of the Consultative Committee', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1924-2867', 'Decree 2867/1924', 'مرسوم إنشاء مجلس المديرين', 'Décret n° 2867 créant le Conseil des Administrateurs', 'Decree No. 2867 Establishing the Council of Administrators', '1924-12-22', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - Governor General Vandenberg issued this decree establishing the Council of Administrators and changing the title to Administrator of Justice', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1925-3018', 'Decision 3018/1925', 'قرار منح محكمة التمييز صلاحيات قانونية وجزائية', 'Décision n° 3018 conférant à la Cour de cassation des compétences juridiques et pénales', 'Decision No. 3018 Granting the Court of Cassation Legal and Penal Jurisdiction', '1925-03-09', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - Decision establishing the Court of Cassation''s jurisdiction, later cancelled by Decree 6/1930', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1926-005', 'Decree 5/1926', 'مرسوم نظام الوزارات الجديد واختصاصاتها', 'Décret n° 5 concernant le nouveau règlement des ministères de la République libanaise et leurs compétences', 'Decree No. 5 Concerning the New Regulations of the Ministries of the Lebanese Republic and Their Powers', '1926-05-31', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - After the proclamation of the Constitution on May 23, 1926, the government adopted this decree establishing the ministries of the Lebanese Republic', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1930-006', 'Legislative Decree 6/1930', 'المرسوم التشريعي رقم 6 المتعلق بتنظيم القضاء', 'Décret législatif n° 6 du 30 février 1930 portant organisation judiciaire', 'Legislative Decree No. 6 of February 30, 1930 on Judicial Organization', '1930-02-30', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - Major judicial reorganization decree that established the structure of Lebanese courts including religious courts for Sunni and Jafari communities', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1934-178LR', 'Decision 178 L.R./1934', 'القرار رقم 178 ل.ر. بإعادة إنشاء محكمة التمييز', 'Décision n° 178 L.R. rétablissant la Cour de cassation', 'Decision No. 178 L.R. Reestablishing the Court of Cassation', '1934-08-10', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - Decision reestablishing the Court of Cassation after it was abolished by Decree 6/1930', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1932-055', 'Decree LR/55/1932', 'مرسوم تعليق العمل بالدستور', 'Décret L.R. n° 55 suspendant la Constitution', 'Decree LR No. 55 Suspending the Constitution', '1932-05-09', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - High Commissioner Henri Ponsot suspended the Constitution and established the Board of Directors, returning to the Directorate of Justice designation', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1939-010LE', 'Decree 10/LE/1939', 'مرسوم إدارة دولة لبنان', 'Décret n° 10/L.E. établissant la gestion de l''État du Liban', 'Decree No. 10/L.E. Establishing the Management of the State of Lebanon', '1939-11-22', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - Signed by President Emile Edde, Secretary of State Abdallah Bayhom, and ratified by High Commissioner Puaux. Later revoked on December 1, 1941 following the creation of Ahmad Daouk''s government', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1939-324LR', 'Decision 324 L.R./1939', 'القرار رقم 324 ل.ر. إلغاء محكمة التمييز وإنشاء مجلس الدولة', 'Décision n° 324 L.R. abolissant la Cour de cassation et créant le Conseil d''État', 'Decision No. 324 L.R. Abolishing the Court of Cassation and Establishing the State Council', '1939-11-22', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - Decision separating administrative judiciary from civil judiciary by creating the State Council', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1932-COC', 'Code of Obligations and Contracts 1932', 'قانون الالتزامات والعقود', 'Code des Obligations et Contrats du 9 mars 1932', 'Code of Obligations and Contracts of March 9, 1932', '1932-03-09', 'Legislative Decree - Mandate Period', NULL, 'active', 'French Mandate period - The most notable code promulgated during the French Mandate, equivalent to the French Civil Code except for personal status matters. Still in force today with amendments.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1924-2385', 'Resolution 2385/1924', 'قرار نظام حقوق الملكية التجارية والصناعية', 'Résolution n° 2385 du 17 janvier 1924 sur le système des droits de propriété commerciale et industrielle', 'Resolution No. 2385 of January 17, 1924 on the System of Commercial and Industrial Property Rights', '1924-01-17', 'Legislative Decree - Mandate Period', NULL, 'amended', 'French Mandate period - High Commissioner General Wegan issued this resolution establishing intellectual property protection in Syria and Lebanon under French mandate', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1926-CONSTITUTION', 'Constitution of May 23, 1926', 'دستور الجمهورية اللبنانية الصادر في 23 أيار 1926', 'Constitution de la République libanaise du 23 mai 1926', 'Constitution of the Lebanese Republic of May 23, 1926', '1926-05-23', 'Legislative Decree - Mandate Period', NULL, 'amended', 'French Mandate period - The Lebanese Constitution was adopted on May 23, 1926, drafted primarily by French authorities with limited Lebanese input. It established the confessional system and was inspired by the French Third Republic. Articles 90-94 relating to the Mandate were abolished in 1943.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1943-464', 'Decision 464/1943', 'القرار رقم 464 إلغاء تعديلات الدستور', 'Décision n° 464 annulant les amendements constitutionnels', 'Decision No. 464 Annulling the Constitutional Amendments', '1943-11-11', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - After Lebanese Parliament amended the Constitution on November 8, 1943 to remove articles contradicting independence, France retaliated with Decisions 464 and 465, annulling amendments, dissolving Parliament, and suspending the Constitution', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1943-465', 'Decision 465/1943', 'القرار رقم 465 تعليق الدستور وتشكيل حكومة بديلة', 'Décision n° 465 suspendant la Constitution et formant un gouvernement alternatif', 'Decision No. 465 Suspending the Constitution and Forming an Alternative Government', '1943-11-11', 'Legislative Decree - Mandate Period', NULL, 'historical', 'French Mandate period - French authorities arrested President Bechara el Khoury, Prime Minister Riad el Solh, and ministers on November 11, 1943, taking them to Rashaya citadel. This sparked national and international protests leading to independence on November 22, 1943', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1943-INDEPENDENCE', 'Independence Day - November 22, 1943', 'استقلال لبنان - 22 تشرين الثاني 1943', 'Indépendance du Liban - 22 novembre 1943', 'Independence of Lebanon - November 22, 1943', '1943-11-22', 'Legislative Decree - Mandate Period', NULL, 'historical', 'Independence - Under British and international pressure, General Catroux ordered the release of Lebanese leaders before noon on November 22, 1943. This day is celebrated as Lebanese Independence Day marking the end of the French Mandate.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1944-797K', 'Decree 797/K/1944', 'مرسوم تنظيم وزارة العدلية الأول', 'Décret n° 797/K du 6 mars 1944 portant premier règlement du Ministère de la Justice', 'Decree No. 797/K of March 6, 1944 on the First Regulation of the Ministry of Justice', '1944-03-06', 'Legislative Decree - Mandate Period', NULL, 'historical', 'Post-Independence - First regulation of the Ministry of Justice after independence, issued by the Lebanese government', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1920-LAND', 'Decree Establishing Land Registry 1920', 'مرسوم إنشاء مصلحة السجل العقاري', 'Décret créant le Service du Cadastre', 'Decree Establishing the Land Registry Service', '1920-01-01', 'Legislative Decree - Mandate Period', NULL, 'amended', 'French Mandate period - The Régie de Travaux du Cadastre et d''Aménagement Foncière was established in 1920 to modernize land administration. By 1925, significant land concentration occurred in the Beqaa where nearly 78% of land was held by a small number of families.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1930-RealProperty', 'Real Property Law 1930', 'قانون الملكية العقارية 1930', 'Loi sur la Propriété Immobilière 1930', 'Real Property Law 1930', '1930-01-01', 'Legislative Decree - Mandate Period', NULL, 'amended', 'French Mandate period - The 1930 Real Property Law was a hybrid between Ottoman and French land regimes, further blurring the distinction between state domains and private holdings, enabling elite capture of land.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1983-150', 'Legislative Decree 150/1983', 'المرسوم التشريعي رقم 150 قانون تنظيم القضاء', 'Décret législatif n° 150 du 16 septembre 1983 sur l''organisation judiciaire', 'Legislative Decree No. 150 of September 16, 1983 on Judicial Organization', '1983-09-16', 'Legislative Decree - Post-Mandate', NULL, 'active', 'Post-Mandate - Legislative Decree No. 150/1983 adopted the text of the Code of Judicial Organization issued in 1961, organizing the Court of Cassation and the State Council. It remains the primary law governing judicial organization in Lebanon today.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1975-10434', 'Law 10434/1975', 'قانون مجلس الدولة', 'Loi n° 10434 du 14 juin 1975 portant création du Conseil d''État', 'Law No. 10434 of June 14, 1975 Establishing the State Council', '1975-06-14', 'Legislative Decree - Post-Mandate', NULL, 'active', 'Post-Mandate - Law enacted by decree No. 10434 of June 14, 1975 established the State Council as the supreme body for administrative jurisdiction, separating it from the Court of Cassation.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1951-ChristianPS', 'Law of April 2, 1951', 'قانون 2 نيسان 1951 الأحوال الشخصية للطوائف المسيحية والإسرائيلية', 'Loi du 2 avril 1951 sur le statut personnel des communautés chrétiennes et israélite', 'Law of April 2, 1951 on Personal Status of Christian and Israelite Communities', '1951-04-02', 'Legislative Decree - Post-Mandate', NULL, 'active', 'Post-Mandate - Following the expansion of Sunni and Jafari religious courts jurisdiction by Legislative Decree 6/1930, this law expanded Christian religious courts jurisdiction to be on par with Islamic courts, sparking protests from the Bar Association.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1942-SunniShia', 'Legislative Decree 6/1930 (Articles on Religious Courts)', 'المواد المتعلقة بالمحاكم الشرعية السنية والجعفرية في المرسوم التشريعي رقم 6', 'Articles relatifs aux tribunaux religieux sunnites et jaafarites du Décret législatif n° 6', 'Articles on Sunni and Jafari Religious Courts from Legislative Decree No. 6', '1930-02-30', 'Legislative Decree - Mandate Period', NULL, 'amended', 'French Mandate period - Legislative Decree 6/1930 organized Sunni and Jafari religious courts, granting them jurisdiction over personal status matters for Muslim communities. Later modified by Law 16/07/1962.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1935-126', 'Legislative Decree 126/1935', 'المرسوم التشريعي رقم 126 بتاريخ 30 أيار 1935 المتعلق بالقضاء العسكري', 'Décret législatif n° 126 du 30 mai 1935 sur la justice militaire', 'Legislative Decree No. 126 of May 30, 1935 on Military Justice', '1935-05-30', 'Legislative Decree - Mandate Period', NULL, 'amended', 'French Mandate period - Legislative Decree No. 126 of May 30, 1935 applied the French Military Penal Code in Syria and Lebanon, replacing Ottoman military laws. This code continued in force even after the mandate ended until amended by Legislative Decree No. 15/1949 and replaced by Law 61/1950.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1918-OPC', 'Ottoman Penal Code (continued in force)', 'القانون العقوبي العثماني المعدل (الساري حتى 1943)', 'Code pénal ottoman amendé (en vigueur jusqu''en 1943)', 'Ottoman Penal Code Amended (in force until 1943)', '1918-01-01', 'Legislative Decree - Mandate Period', NULL, 'repealed', 'French Mandate period - The Ottoman Penal Code continued in force during the French Mandate with amendments. Article 534 criminalizing homosexual practices is often mistakenly attributed to the French Mandate, but research suggests it was influenced by Jesuit-Maronite moral theology rather than French colonial law, as French penal codes had not criminalized same-sex relations since 1791.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1943-1109', 'Constitutional Law November 9, 1943', 'القانون الدستوري 9 تشرين الثاني 1943', 'Loi constitutionnelle du 9 novembre 1943', 'Constitutional Law of November 9, 1943', '1943-11-09', 'Legislative Decree - Mandate Period', NULL, 'active', 'Independence - Constitutional amendments adopted on November 8, 1943 by Parliament removed all references to the French Mandate from the Constitution. France responded with Decisions 464 and 465, but under international pressure, recognized independence on November 22, 1943.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1959-CivilService', 'Legislative Decree 111/1959', 'المرسوم التشريعي رقم 111 تاريخ 12 حزيران 1959 تنظيم وزارة العدل', 'Décret législatif n° 111 du 12 juin 1959 organisant le Ministère de la Justice', 'Legislative Decree No. 111 of June 12, 1959 Organizing the Ministry of Justice', '1959-06-12', 'Legislative Decree - Post-Mandate', NULL, 'active', 'Post-Mandate - Legislative Decree No. 111/1959 organized the Ministry of Justice. This was part of the legislative reforms during President Fouad Chehab''s mandate (1958-1964), which included the Civil Service Law and Judiciary Organization laws.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1943-NationalPact', 'National Pact 1943 (Unwritten Agreement)', 'الميثاق الوطني 1943', 'Pacte National 1943', 'National Pact 1943', '1943-09-25', 'Legislative Decree - Mandate Period', NULL, 'historical', 'Independence - The National Pact was an unwritten agreement adopted around September 25, 1943 between Christian and Muslim leaders. It established the confessional power-sharing formula: President (Maronite), Prime Minister (Sunni), Speaker (Shia), and 6:5 Christian-Muslim ratio in Parliament. It was based on the 1932 census showing Christians as slight majority.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LD-1989-Taif', 'Taif Agreement - Constitutional Law September 21, 1990', 'اتفاق الطائف - القانون الدستوري 21 أيلول 1990', 'Accord de Taëf - Loi constitutionnelle du 21 septembre 1990', 'Taif Agreement - Constitutional Law of September 21, 1990', '1989-10-22', 'Legislative Decree - Post-Mandate', NULL, 'active', 'Post-Mandate - The Taif Agreement was signed on October 22, 1989 in Taif, Saudi Arabia to end the Lebanese Civil War (1975-1990). It amended the Constitution to provide equal representation between Christians and Muslims in Parliament (previously 6:5), strengthened the Council of Ministers at the expense of the President, and called for gradual abolition of political confessionalism.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-001', 'Arrêté No. 2385 of January 17, 1924', NULL, NULL, 'Trademarks and Trade Names', '1924-01-17', 'Commercial Law', NULL, 'amended', 'Trademark registration and protection system. One of the oldest still-enforced laws.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-002', 'Arrêté No. 3339 of November 12, 1930', NULL, NULL, 'Real Property Law', '1930-11-12', 'Civil Law', NULL, 'amended', 'Modern property registration (Torrens) system replacing Ottoman land categories.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-003', 'Law of March 9, 1932 (Code of Obligations and Contracts)', NULL, NULL, 'Code of Obligations and Contracts', '1932-03-09', 'Civil Law', NULL, 'amended', 'Primary civil law code. See civil_code.json for full entry.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-004', 'Arrêté No. 15 of March 3, 1930', NULL, NULL, 'Water Law', '1930-03-03', 'Administrative & Municipal', NULL, 'amended', 'Water rights and concessions. Foundation of Lebanese water law.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-005', 'Arrêté No. 144/S of November 10, 1925', NULL, NULL, 'Forests Law', '1925-11-10', 'Environmental', NULL, 'amended', 'Forest protection and management. One of the earliest environmental protection laws.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-006', 'Arrêté No. 2866 of December 16, 1959', NULL, NULL, 'Press and Publications Law', '1962-09-14', 'Media & Press', NULL, 'amended', 'Governs print media, press freedom, journalist protections, and publication licensing.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-007', 'Decree No. 11614 of January 4, 1969', NULL, NULL, 'Acquisition of Real Property by Foreigners', '1969-01-04', 'Property & Real Estate', NULL, 'amended', 'Regulates foreign ownership of real property in Lebanon. Restricts foreign ownership based on area limits and requires prior approval.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-008', 'Legislative Decree No. 340 of March 1, 1943', NULL, NULL, 'Penal Code', '1943-03-01', 'Criminal Law', NULL, 'amended', 'See penal_code.json for full entry.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-009', 'Code of Commerce of December 24, 1942', NULL, NULL, 'Code of Terrestrial Commerce', '1942-12-24', 'Commercial Law', NULL, 'amended', 'See commercial_code.json for full entry.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-010', 'Decree No. 1307 of March 10, 1922', NULL, NULL, 'Electoral Law (First)', '1922-03-10', 'Electoral Law', NULL, 'repealed', 'First electoral law for the Representative Council. Established confessional seat allocation.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-011', 'Arrêté of October 13, 1926', NULL, NULL, 'Government Accounting Law', '1926-10-13', 'Tax & Fiscal', NULL, 'amended', 'Public accounting and government financial management rules.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-012', 'Arrêté No. 60/LR of March 13, 1936', NULL, NULL, 'Land Registration Law', '1936-03-13', 'Property & Real Estate', NULL, 'amended', 'Land surveying and cadastral registration system.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-013', 'Decree-Law No. 340-bis of 1943', NULL, NULL, 'Military Penal Code', '1943-03-01', 'Military & Security', NULL, 'amended', 'Penal code for military offenses and military court jurisdiction.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-014', 'Arrêté No. 336 of December 28, 1926', NULL, NULL, 'Organization of the Conseil d''État', '1926-12-28', 'Judicial Organization', NULL, 'amended', 'Established the administrative court system (Conseil d''État / مجلس شورى الدولة).', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-LD-015', 'Ottoman Nationality Law of 1869 + Arrêté No. 15/S of January 19, 1925', NULL, NULL, 'Lebanese Nationality Law', '1925-01-19', 'Civil Law', NULL, 'amended', 'Foundation of Lebanese nationality law. Established who qualifies as Lebanese. Controversially, nationality passes primarily through the father (patrilineal system). Decades-long campaign for women to pass nationality to their children has not yet succeeded.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-MUN-001', 'Legislative Decree No. 118 of June 30, 1977 (Municipal Act)', 'مرسوم اشتراعي رقم 118/1977 - البلديات', 'Décret législatif No. 118/1977 - Loi Municipale', 'Municipal Act / Municipalities Law', '1977-06-30', 'Administrative & Municipal', 'Municipal Law', 'amended', 'Primary law governing Lebanon''s 1,064 municipalities. Enacted during the early civil war period. Defines municipal powers, elections, budgets, and relationship with central government. Article 16 states that parliamentary election provisions apply to municipal elections. Municipal elections are held separately from parliamentary elections. Municipalities manage local affairs including urban planning, waste management, local roads, and public spaces. Lebanon also has 51 municipal unions (federations of municipalities).', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-MUN-002', 'Decree No. 1166 of August 19, 1959 (Moukhtars)', 'مرسوم رقم 1166/1959 - المختارين', 'Décret No. 1166/1959 - Mouhtars', 'Moukhtar (Village/Neighborhood Chief) Law', '1959-08-19', 'Administrative & Municipal', 'Local Administration', 'amended', 'Governs the office of moukhtar (مختار), the elected neighborhood/village chief. Lebanon has 3,018 moukhtars who serve as local administrative officials handling personal status documentation, attestations, and acting as intermediaries between citizens and government agencies.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-ELECT-001', 'Law No. 44 of June 17, 2017 (Parliamentary Elections)', 'قانون انتخاب أعضاء مجلس النواب - قانون رقم 44/2017', 'Loi No. 44/2017 - Élection des Membres du Parlement', 'Parliamentary Elections Law', '2017-06-17', 'Electoral Law', 'Parliamentary Elections', 'amended', 'Replaced Electoral Law No. 25/2008. Landmark reform: introduced proportional representation for the first time in Lebanese history (replacing winner-takes-all majoritarian system). Key features: 15 electoral districts, preferential voting within party lists, diaspora voting provisions (Article 3), establishment of Supervisory Commission for Elections, campaign finance regulations including lifting banking secrecy for campaign accounts. The law was used for the 2018 and 2022 parliamentary elections. Previous electoral laws: Law 25/2008, Law 171/2000, Law of 1960.', 125) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-MUN-003', 'Law No. 216 of April 2, 1993 (Urban Planning / Construction)', 'قانون البناء', 'Loi sur la Construction / Urbanisme', 'Building/Construction Law', '1993-04-02', 'Administrative & Municipal', 'Urban Planning', 'amended', 'Governs building permits, construction standards, zoning, and urban planning regulations. Administered by the Directorate General of Urban Planning (DGU) and the Order of Engineers and Architects. Post-war reconstruction generated significant construction activity, making this law particularly important.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-MUN-004', 'Law No. 444 of August 12, 2002 (Environmental Protection)', 'قانون حماية البيئة - قانون رقم 444/2002', 'Loi No. 444/2002 - Protection de l''Environnement', 'Environmental Protection Law', '2002-08-12', 'Environmental', 'General Environmental Law', 'active', 'Lebanon''s primary environmental legislation. Established the Ministry of Environment''s mandate, environmental impact assessment requirements, pollution control standards, and nature protection provisions. Implementation has been criticized as weak due to institutional capacity constraints.', 65) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-MUN-005', 'Law No. 462 of September 2, 2002 (Council for Development & Reconstruction)', 'قانون مجلس الإنماء والإعمار', 'Loi sur le Conseil de Développement et de Reconstruction (CDR)', 'Council for Development and Reconstruction (CDR) Law', '1977-01-01', 'Administrative & Municipal', 'Development', 'active', 'Established the CDR as the primary government body for physical infrastructure reconstruction and development project management. Originally created in 1977 for post-war reconstruction, it became the main conduit for international development funding to Lebanon.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-MUN-006', 'Law No. 28 of February 11, 2017 (Access to Information)', 'قانون الحق في الوصول إلى المعلومات - قانون رقم 28/2017', 'Loi No. 28/2017 - Droit d''Accès à l''Information', 'Right to Access Information Law', '2017-02-11', 'Administrative & Municipal', 'Transparency', 'active', 'Landmark transparency legislation granting citizens the right to access information held by government entities. Requires proactive publication of certain categories of information. Establishes procedures for information requests and exemptions. Implementation has been gradual, with the National Anti-Corruption Commission taking on oversight responsibilities.', 30) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-MUN-007', 'Law No. 175 of May 8, 2020 (Anti-Corruption / National Anti-Corruption Commission)', 'قانون مكافحة الفساد في القطاع العام وإنشاء الهيئة الوطنية لمكافحة الفساد', 'Loi No. 175/2020 - Lutte contre la Corruption', 'Anti-Corruption in the Public Sector and Establishment of the National Anti-Corruption Commission Law', '2020-05-08', 'Administrative & Municipal', 'Anti-Corruption', 'active', 'Established the National Anti-Corruption Commission (NACC) and criminalized corruption in the public sector. Part of a package of reform laws demanded by the international community. The NACC was eventually formed in 2022 after delays in appointing commissioners.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-MUN-008', 'Law No. 189 of October 16, 2020 (Whistleblower Protection)', 'قانون حماية كاشفي الفساد - قانون رقم 189/2020', 'Loi No. 189/2020 - Protection des Dénonciateurs de Corruption', 'Whistleblower Protection Law', '2020-10-16', 'Administrative & Municipal', 'Anti-Corruption', 'active', 'Provides legal protections for individuals who report corruption in the public and private sectors. Covers protection from retaliation, confidentiality guarantees, and procedures for reporting.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-MUN-009', 'Decree No. 2791 of December 8, 1959 (Associations Law)', 'قانون الجمعيات العثماني 1909 ومرسوم 2791/1959', 'Loi Ottomane de 1909 sur les Associations et Décret 2791/1959', 'Law of Associations', '1909-08-03', 'Administrative & Municipal', 'Civil Society', 'amended', 'One of the oldest still-operative laws in Lebanon, dating from the Ottoman period (1909). Governs the formation and operation of non-profit associations, clubs, and civil society organizations. Requires notification (ilm wa khabar) to the Ministry of Interior for formation. Despite its age, the law provides a relatively permissive framework for civil society. Decree 2791/1959 supplemented Ottoman-era provisions. The law also governs political parties, which has been criticized as outdated.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-MUN-001', 'Decree-Law 118/1977', 'قانون البلديات - المرسوم الاشتراعي رقم 118 تاريخ 30/6/1977', 'Décret-loi n° 118 du 30 juin 1977 - Loi sur les Municipalités', 'Municipal Act - Decree-Law No. 118 dated June 30, 1977', '1977-06-30', 'Municipal Law', NULL, 'active', 'The Municipal Law was enacted during the Lebanese Civil War (1975-1990) as a framework for local governance. It replaced previous Ottoman and French Mandate-era municipal legislation. The law established the foundation for municipal autonomy while maintaining central government oversight. It was significantly amended by Law 665/1997 to update electoral procedures and municipal governance structures.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-URB-001', 'Decree-Law 69/1983', 'قانون التنظيم المدني والتعمير - المرسوم الاشتراعي رقم 69 تاريخ 9/9/1983', 'Décret-loi n° 69 du 9 septembre 1983 - Code de l''Urbanisme', 'Urban Planning Code - Decree-Law No. 69 dated September 9, 1983', '1983-09-09', 'Urban Planning Law', NULL, 'active', 'The Urban Planning Code was enacted during the Lebanese Civil War to modernize urban planning regulations. It established the framework for master plans, building permits, and land subdivision. The law created mechanisms for large-scale development projects including the establishment of real estate companies like SOLIDERE for Beirut city center reconstruction.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-ENV-001', 'Law 444/2002', 'قانون حماية البيئة في لبنان - القانون رقم 444 تاريخ 29/7/2002', 'Loi n° 444 du 29 juillet 2002 - Loi sur la Protection de l''Environnement', 'Environmental Protection Law - Law No. 444 dated July 29, 2002', '2002-07-29', 'Environmental Law', NULL, 'active', 'Law 444/2002 is Lebanon''s overarching environmental protection legislation, enacted to align with international environmental conventions. It established the framework for Environmental Impact Assessments (EIA) and Strategic Environmental Assessments (SEA) through subsequent decrees. The law reflects principles from international treaties including the polluter-pays principle, precautionary principle, and public participation.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-CON-001', 'Law 646/2004', 'قانون البناء - القانون رقم 646 تاريخ 2004', 'Loi n° 646 de 2004 - Loi sur la Construction', 'Construction Law / Building Code - Law No. 646 of 2004', '2004', 'Construction Law', NULL, 'active', 'The Construction Law 646/2004 replaced older building regulations and introduced modern construction standards. It includes provisions for environmental protection during construction, building envelope ratios, and exploitation factors. The law was implemented through decrees in 2005 and 2007. It is the centerpiece of all construction activities in Lebanon.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-PROC-001', 'Law 244/2021', 'قانون المناقصات العامة - القانون رقم 244 تاريخ 19/7/2021', 'Loi n° 244 du 19 juillet 2021 - Loi sur les Marchés Publics', 'Public Procurement Law - Law No. 244 dated July 19, 2021', '2021-07-19', 'Public Procurement Law', NULL, 'active', 'The Public Procurement Law 244/2021 replaced Lebanon''s outdated procurement system from the 1960s. It was enacted as part of reforms demanded by the International Monetary Fund and international community. The law introduces competitive bidding as the default, establishes a central e-procurement platform, and creates a Complaints Authority for dispute resolution. It entered into force 12 months after publication (July 2022).', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-ADMIN-001', 'Decree 10434/1975', 'نظام مجلس الشورى - المرسوم رقم 10434 تاريخ 14/6/1975', 'Décret n° 10434 du 14 juin 1975 - Règlement du Conseil d''État', 'State Council Organization Law - Decree No. 10434 dated June 14, 1975', '1975-06-14', 'Administrative Law', NULL, 'active', 'The State Council was originally established in 1924 during the French Mandate. Decree 10434/1975 reorganized the State Council during the early period of the Lebanese Civil War. The law was amended by Law 227/2000 which provided for the establishment of first-level administrative tribunals in each governorate, though these have not yet been implemented. The State Council serves as both an administrative court and advisory body to the government.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-CIVIL-001', 'Decree-Law 112/1959', 'نظام موظفي الإدارة العامة - المرسوم الاشتراعي رقم 112 تاريخ 12/6/1959', 'Décret-loi n° 112 du 12 juin 1959 - Statut des fonctionnaires', 'Civil Service Law - Decree-Law No. 112 dated June 12, 1959', '1959-06-12', 'Civil Service Law', NULL, 'active', 'The Civil Service Law was enacted shortly after Lebanon gained independence to establish a professional public administration. It created the framework for civil service recruitment, promotion, discipline, and rights. Decree 114/1959 established the Civil Service Board to oversee civil service matters. The law applies to central government employees and certain municipalities designated as governorate centers.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-PROP-001', 'Law 58/1991', 'قانون نزع الملكية للمنفعة العامة - القانون رقم 58 تاريخ 29/5/1991', 'Loi n° 58 du 29 mai 1991 - Loi sur l''Expropriation pour Utilité Publique', 'Expropriation Law - Law No. 58 dated May 29, 1991', '1991-05-29', 'State Property Law', NULL, 'active', 'The Expropriation Law was enacted after the Lebanese Civil War to regulate land acquisition for reconstruction and public projects. It implements Article 15 of the Lebanese Constitution which guarantees private property rights while allowing expropriation for public utility with fair compensation. The law establishes the framework for Expropriation Committees and Appellate Expropriation Committees.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-ENV-002', 'Law 78/2018', 'قانون حماية جودة الهواء - القانون رقم 78 تاريخ 19/4/2018', 'Loi n° 78 du 19 avril 2018 - Loi sur la Protection de la Qualité de l''Air', 'Air Quality Protection Law - Law No. 78 dated April 19, 2018', '2018-04-19', 'Environmental Law', NULL, 'active', 'Law 78/2018 was enacted to address Lebanon''s significant air pollution problems, particularly in urban areas. The law establishes the National Ambient Air Quality Standards (NAAQS) and creates frameworks for monitoring air pollutants, emission inventories, and early warning systems. It complements Law 444/2002 and aligns with Lebanon''s commitments under the UNFCCC and Paris Agreement.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-ENV-003', 'Law 80/2018', 'قانون إدارة النفايات الصلبة المتكاملة - القانون رقم 80 تاريخ 24/9/2018', 'Loi n° 80 du 24 septembre 2018 - Loi sur la Gestion Intégrée des Déchets Solides', 'Integrated Solid Waste Management Law - Law No. 80 dated September 24, 2018', '2018-09-24', 'Environmental Law', NULL, 'active', 'Law 80/2018 was enacted in response to Lebanon''s severe waste management crisis that began in 2015. The law provides a framework for integrated solid waste management including provisions for waste sorting, recycling, and treatment. However, critics note it lacks detailed implementation mechanisms and does not adequately address waste prevention, reuse, or extended producer responsibility. The law is currently being amended to address municipal financing issues.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-ENV-004', 'Law 49/1949', 'قانون الغابات - القانون رقم 49 تاريخ 1949', 'Loi n° 49 de 1949 - Code Forestier', 'Forest Law / Forest Code - Law No. 49 of 1949', '1949', 'Environmental Law', NULL, 'active', 'The Forest Law of 1949 is one of the oldest environmental laws in Lebanon and the region, covering forests that were under the French Mandate. It was amended by Law 85/1991 which imposed severe restrictions on forest activities and banned harvesting from resinous trees (cedar, fir, cypress, oak, juniper). Law 558/1996 further strengthened protection by considering all coniferous forests as protected. Law 195/2000 criminalized illegal operations.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-ENV-005', 'Water Law 2000', 'قانون المياه - قانون عام 2000', 'Loi sur l''Eau - Loi de 2000', 'Water Law - Law of 2000', '2000', 'Environmental Law', NULL, 'active', 'The Water Law of 2000 governs the management and use of Lebanon''s water resources, including surface water and groundwater. It establishes the framework for Water Establishments (WEs) and their financial autonomy, though the Ministry of Energy and Water maintains significant oversight. The law addresses water scarcity issues exacerbated by urbanization, pollution, and climate change.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-MUN-002', 'Law 665/1997', 'قانون تعديل قانون البلديات - القانون رقم 665 تاريخ 30/12/1997', 'Loi n° 665 du 30 décembre 1997 - Loi modifiant la Loi sur les Municipalités', 'Municipal Law Amendment - Law No. 665 dated December 30, 1997', '1997-12-30', 'Municipal Law', NULL, 'active', 'Law 665/1997 is a significant amendment to the Municipal Law 118/1977. It updated the composition of municipal councils based on population, modified election procedures, and established clearer rules for municipal governance. The law has been criticized for facilitating the proliferation of municipalities by making their establishment a prerogative of the Minister of Interior rather than a right based on objective criteria.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-MUN-003', 'Law 60/1988', 'قانون الصندوق البلدي المستقل - القانون رقم 60 تاريخ 1988', 'Loi n° 60 de 1988 - Loi sur le Fonds Municipal Indépendant', 'Independent Municipal Fund Law - Law No. 60 of 1988', '1988', 'Municipal Law', NULL, 'active', 'Law 60/1988 established the Independent Municipal Fund (IMF) as the main mechanism for financing municipal activities in Lebanon. The fund collects revenues from various sources including a 10% surtax on built properties and distributes them to municipalities. The fund has been criticized for being subject to central government control and political interference in its distribution mechanisms.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-ENV-006', 'Law on Noise Pollution 2004', 'قانون حماية البيئة من التلوث الضوضائي - قانون عام 2004', 'Loi sur la Protection de l''Environnement contre la Pollution Sonore - Loi de 2004', 'Law on the Protection of the Environment from Noise Pollution - Law of 2004', '2004', 'Environmental Law', NULL, 'active', 'The Noise Pollution Law was enacted in 2004 to address growing concerns about noise pollution in Lebanon''s urban areas. The law sets permissible noise levels for different zones and regulates noise-generating activities. However, enforcement has been limited due to weak monitoring capacity and lack of resources.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LEB-ENV-007', 'Law 64/1988', 'قانون حماية البيئة من التلوث بالنفايات الخطرة والمواد الضارة - القانون رقم 64 تاريخ 1988', 'Loi n° 64 de 1988 - Préservation de l''Environnement contre la Pollution par les Déchets Dangereux et les Substances Nocives', 'Preservation of the Environment against Pollution from Dangerous Waste and Hazardous Substances - Law No. 64 of 1988', '1988', 'Environmental Law', NULL, 'active', 'Law 64/1988 was one of Lebanon''s earliest environmental protection laws, addressing pollution from dangerous waste and hazardous substances. It was enacted before the comprehensive Environmental Protection Law 444/2002 and remains in force for specific hazardous waste matters.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CIV-001-EXPANDED', NULL, 'قانون الموجبات والعقود', NULL, 'Code of Obligations and Contracts (1932) - Expanded', '1932-03-09', 'civil', 'obligations_contracts', NULL, 'The Lebanese Code of Obligations and Contracts was promulgated on 9 March 1932 during the French Mandate period. It is heavily influenced by the French Civil Code and the Ottoman Mejelle. The Code contains 1,106 articles organized into several books covering general obligations, specific contracts, and civil liability. It remains the foundational civil law text in Lebanon governing contractual relationships, torts, property, and civil obligations.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CRIM-001', 'Decree-Law No. 340 of March 1, 1943', 'قانون العقوبات - مرسوم اشتراعي رقم 340 تاريخ 1 آذار 1943', 'Code Pénal - Décret-loi No. 340 du 1er mars 1943', 'Penal Code', '1943-03-01', 'Criminal Law', 'General Penal Code', 'amended', 'Enacted during the French Mandate, the Lebanese Penal Code was modeled on the French Penal Code and the Syrian Penal Code (itself French-derived). It has undergone significant reforms in recent decades, particularly regarding women''s rights (repeal of honor crime provisions), domestic violence criminalization, torture prohibition, and sexual harassment. Lebanon retains the death penalty in the code but has maintained a de facto moratorium on executions since 2004. Key ongoing reform debates include: decriminalization of drug use (Article 127-related), defamation reform, and LGBTQ+ rights (Article 534 criminalizing ''unnatural'' sexual relations remains controversial).', 772) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CRIM-002', 'Law No. 328 of August 2, 2001 (Code of Criminal Procedure)', 'قانون أصول المحاكمات الجزائية - قانون رقم 328/2001', 'Code de Procédure Pénale - Loi No. 328/2001', 'Code of Criminal Procedure', '2001-08-02', 'Criminal Law', 'Criminal Procedure', 'amended', 'Replaced the previous Code of Criminal Procedure (dating from 1948/French Mandate era). Modernized criminal procedure including pre-trial detention rules, rights of the accused, investigation procedures, trial procedures, and appeals. Introduced greater protections for suspects and defendants, including limits on pre-trial detention and right to counsel. However, implementation has been criticized by human rights organizations for gaps in practice.', 420) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CRIM-003', 'Law No. 293 of April 1, 2014', 'قانون حماية النساء وسائر أفراد الأسرة من العنف الأسري - قانون رقم 293/2014', 'Loi No. 293/2014 relative à la protection des femmes et des membres de la famille contre la violence domestique', 'Law on Protection of Women and Family Members from Domestic Violence', '2014-04-01', 'Criminal Law', 'Domestic Violence', 'active', 'Landmark legislation criminalizing domestic violence in Lebanon. Result of years of civil society advocacy, particularly by KAFA (Enough) Violence & Exploitation. Introduced protection orders, established specialized procedures for domestic violence cases, and created the offense of family violence. Criticized by some women''s rights organizations for not going far enough, particularly regarding marital rape provisions which were weakened during parliamentary debate.', 22) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CRIM-004', 'Law No. 673 of February 16, 1998 (Narcotics)', 'قانون المخدرات والمؤثرات العقلية - قانون رقم 673/1998', 'Loi No. 673/1998 sur les Stupéfiants et Substances Psychotropes', 'Narcotics, Drugs and Psychotropic Substances Law', '1998-02-16', 'Criminal Law', 'Narcotics', 'amended', 'Comprehensive narcotics legislation replacing earlier laws. Covers production, trafficking, possession, and use of narcotic drugs and psychotropic substances. Provides for treatment alternatives for drug users (Article 127). Ongoing debate about reforming drug policy in Lebanon, with civil society organizations advocating for decriminalization of personal use.', 210) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CRIM-005', 'Law No. 65 of September 19, 2017 (Anti-Torture)', 'قانون تجريم التعذيب - قانون رقم 65/2017', 'Loi No. 65/2017 incriminant la torture', 'Law Criminalizing Torture and Other Cruel, Inhuman or Degrading Treatment or Punishment', '2017-09-19', 'Criminal Law', 'Human Rights', 'active', 'Landmark human rights legislation criminalizing torture. Enacted to bring Lebanon into compliance with the Convention Against Torture (ratified 2000). Defines torture as a crime, establishes penalties including imprisonment, and provides for victims'' compensation. Also established the National Preventive Mechanism against Torture.', 15) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-CRIM-001', 'Legislative Decree 340/1943', 'قانون العقوبات', 'Code Pénal', 'Penal Code', '1943-03-01', 'Criminal Law', NULL, 'active', 'The Lebanese Penal Code was enacted on March 1, 1943, by Legislative Decree No. 340, shortly before Lebanon''s independence. It replaced the Ottoman Penal Code and was heavily influenced by French criminal law. The Code has been amended numerous times, particularly regarding penalties, corruption offenses, and crimes against children.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-CRIM-002', 'Law 328/2001', 'قانون أصول المحاكمات الجزائية', 'Code de Procédure Pénale', 'Code of Criminal Procedure', '2001-08-02', 'Procedure', NULL, 'active', 'The Code of Criminal Procedure was enacted by Law No. 328 of August 2, 2001, and published in the Official Gazette on August 7, 2001. It replaced the previous Code of Criminal Procedure of 1948 and subsequent amendments. The new Code was a comprehensive reform of criminal procedure in Lebanon, incorporating international standards and human rights principles. It has been amended multiple times to address emerging issues including trafficking in persons.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-CRIM-003', 'Law 24/1968', 'قانون أصول المحاكمات العسكرية', 'Code de Justice Militaire', 'Code of Military Justice', '1968-04-13', 'Criminal Law', NULL, 'active', 'The Code of Military Justice was enacted by Law No. 24 of April 13, 1968. It establishes the military court system in Lebanon, which includes single military judges, the Permanent Military Tribunal, and the Military Court of Cassation. The military courts have jurisdiction over military personnel for military offenses, as well as over certain crimes committed by civilians, including crimes against state security, terrorism-related crimes, and crimes committed in military premises. The Code has been criticized by human rights organizations for allowing the trial of civilians before military courts and for not fully complying with international fair trial standards.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-CRIM-004', 'Law 2/78', 'قانون إنشاء محكمة أمن الدولة الخاصة', 'Loi sur la création d''un tribunal de sécurité d''État spécial', 'Law on Establishment of Special State Security Court', '1978-02-15', 'Criminal Law', NULL, 'repealed', 'The Special State Security Court was established by Law No. 2/78 of February 15, 1978, during the Lebanese Civil War. It was abolished by Decree No. 603 of May 19, 1983, following the end of the war and the restoration of the regular judicial system.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-CRIM-001-EXPANDED', 'Decree-Law No. 340 of March 1, 1943', 'قانون العقوبات', 'Code Pénal', 'Penal Code (Expanded)', '1943-03-01', 'Criminal Law', 'General Penal Code', 'amended', 'Full article-level text of the Lebanese Penal Code (Decree-Law No. 340/1943), extracted from the STL (Special Tribunal for Lebanon) official English translation. This code is the primary criminal law legislation in Lebanon, covering general criminal provisions, felonies, misdemeanors, and contraventions.', 772) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LPS-SUN-001', 'Legislative Decree No. 241 of November 4, 1942; amended by Law No. 177 of 2011', 'نظام أحكام الأسرة للطائفة السنية', 'Code des Dispositions Familiales pour la Communauté Sunnite', 'Code of Family Provisions for the Sunni Community', '1942-11-04', 'Personal Status - Sunni Muslim', NULL, 'active', 'Based on Ottoman Family Rights Law of 1917. The 1962 law organized the Sunni and Jaafari judiciaries. The 2011 amendment (Law 177) was a significant reform raising custody ages following civil society advocacy.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LPS-SHI-002', 'Legislative Decree No. 241 of November 4, 1942; Jaafari Jurisprudence', 'قانون حقوق العائلة للطائفة الجعفرية', 'Loi des Droits de Famille pour la Communauté Jaafari', 'Family Rights Law for the Jaafari Community', '1942-11-04', 'Personal Status - Shia Muslim (Jaafari)', NULL, 'active', 'The Jaafari community was officially recognized in 1926. Unlike Christian sects, Islamic courts require state legislation for establishment. The Jaafari courts apply Jaafari fiqh, fatwas from religious authorities, and the Guide to Jaafari Justice (1944).', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LPS-DRU-003', 'Law of February 24, 1948; amended by Law 58 of October 17, 2017', 'قانون الأحوال الشخصية لطائفة الموحدين الدروز', 'Loi du Statut Personnel de la Communauté Druze des Unificateurs', 'Personal Status Law of the Druze Unifiers Community', '1948-02-24', 'Personal Status - Druze', NULL, 'active', 'First codified personal status law in Lebanon post-independence (1948). The 2017 amendments were groundbreaking, citing constitutional equality principles and reflecting modern social developments. The Druze community has two Sheikhs al-Aql (spiritual leaders).', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LPS-GOR-004', 'Law of October 16, 2003', 'قانون الأحوال الشخصية وصول المحاكمات لدى بطريركية أنطاكية وسائر المشرق للروم الأرثوذكس', 'Loi du Statut Personnel et Procédure des Tribunaux du Patriarcat d''Antioche et de tout l''Orient des Grecs Orthodoxes', 'Personal Status and Court Procedures Law of the Greek Orthodox Patriarchate of Antioch and All the East', '2003-10-16', 'Personal Status - Greek Orthodox', NULL, 'active', 'The 2003 law was a landmark reform emphasizing spousal equality, removing husband authority clauses, and allowing women from other denominations to marry Greek Orthodox men without converting. It was the first major Christian personal status reform in Lebanon.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LPS-MAR-005', 'Law of February 22, 1949; Code of Canons of Eastern Churches 1990', 'قانون الأحوال الشخصية للطوائف الكاثوليكية الشرقية - الموارنة', 'Loi du Statut Personnel des Confessions Catholiques Orientales - Maronites', 'Personal Status Law of Eastern Catholic Confessions - Maronite', '1949-02-22', 'Personal Status - Maronite Catholic', NULL, 'active', 'Maronites are the largest Christian community in Lebanon. They follow the Code of Canons of Eastern Churches (1990) which introduced spousal equality. The 1949 law was the foundation for Catholic personal status laws. Marriage is considered indissoluble sacrament.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LPS-GCA-006', 'Law of February 22, 1949 - Shared Catholic Personal Status Law', 'قانون الأحوال الشخصية للطوائف الكاثوليكية - الروم الكاثوليك (الملكيين)', 'Loi du Statut Personnel des Confessions Catholiques - Grecs Catholiques (Melkites)', 'Personal Status Law of Catholic Confessions - Greek Catholic (Melkite)', '1949-02-22', 'Personal Status - Greek Catholic (Melkite)', NULL, 'active', 'The Melkite Greek Catholic Church follows the same personal status law as other Eastern Catholic confessions. They recognize the Pope but maintain Byzantine liturgical traditions.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LPS-ARO-007', 'Law of February 22, 1949; Code of Procedure January 1, 1990', 'قانون الأحوال الشخصية للطائفة الأرمنية الأرثوذكسية', 'Loi du Statut Personnel de la Confession Arménienne Orthodoxe', 'Personal Status Law of the Armenian Orthodox Confession', '1949-02-22', 'Personal Status - Armenian Orthodox', NULL, 'active', 'The Armenian Orthodox community is unique among Lebanese Christian communities as their personal status law provides for equal parental authority between mothers and fathers. This reflects the Armenian community''s progressive approach to family law.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LPS-ARC-008', 'Law of February 22, 1949; Code of Canons of Eastern Churches 1990; Code of Procedure for Eastern Catholic Tribunals', 'قانون الأحوال الشخصية للطائفة الأرمنية الكاثوليكية', 'Loi du Statut Personnel de la Confession Arménienne Catholique', 'Personal Status Law of the Armenian Catholic Confession', '1949-02-22', 'Personal Status - Armenian Catholic', NULL, 'active', 'Armenian Catholics are one of the six Eastern Catholic communities sharing the unified 1949 Personal Status Law. They recognize the authority of the Pope while maintaining Armenian liturgical and cultural traditions. The 1990 Code of Canons of Eastern Churches (CCEO) introduced spousal equality provisions (Canon 777) that apply to all Eastern Catholic churches. The Armenian Catholic Church has its own patriarchate and follows the Code of Procedure for Tribunals of Eastern Catholic Churches for court procedures.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LPS-SYO-009', 'Law of February 22, 1949; renewed September 10, 2003', 'قانون الأحوال الشخصية لطائفة السريان الأرثوذكس', 'Loi du Statut Personnel de la Confession Syriac Orthodoxe', 'Personal Status Law of the Syriac Orthodox Confession', '1949-02-22', 'Personal Status - Syriac Orthodox', NULL, 'active', 'The Syriac Orthodox Church is one of the ancient Oriental Orthodox churches. Their personal status law was renewed in 2003 by the Synod of Antioch and ratified by Patriarch Ignatius Zakka I.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LPS-SYC-010', 'Law of February 22, 1949; Code of Canons of Eastern Churches 1990; Code of Procedure for Eastern Catholic Tribunals', 'قانون الأحوال الشخصية للطائفة السريانية الكاثوليكية', 'Loi du Statut Personnel de la Confession Syriac Catholique', 'Personal Status Law of the Syriac Catholic Confession', '1949-02-22', 'Personal Status - Syriac Catholic', NULL, 'active', 'Syriac Catholics are one of the six Eastern Catholic communities sharing the unified 1949 Personal Status Law. They recognize the authority of the Pope while maintaining West Syriac liturgical traditions. The 1990 Code of Canons of Eastern Churches (CCEO) introduced significant reforms including spousal equality (Canon 777). The Syriac Catholic Church has its own patriarchate (the Syriac Catholic Patriarchate of Antioch) and follows the Code of Procedure for Tribunals of Eastern Catholic Churches. The community has ancient roots in the Levant and maintains distinct cultural and religious traditions.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LPS-CHL-011', 'Law of February 22, 1949; Code of Canons of Eastern Churches 1990; Code of Procedure for Eastern Catholic Tribunals', 'قانون الأحوال الشخصية للطائفة الكلدانية الكاثوليكية', 'Loi du Statut Personnel de la Confession Chaldéenne Catholique', 'Personal Status Law of the Chaldean Catholic Confession', '1949-02-22', 'Personal Status - Chaldean Catholic', NULL, 'active', 'Chaldean Catholics are one of the six Eastern Catholic communities sharing the unified 1949 Personal Status Law. They recognize the authority of the Pope while maintaining East Syriac liturgical traditions. The 1990 Code of Canons of Eastern Churches (CCEO) introduced significant reforms including spousal equality (Canon 777). The Chaldean Catholic Church has its own patriarchate (the Chaldean Catholic Patriarchate of Babylon) based in Baghdad, with diaspora communities throughout the world including Lebanon. Many Chaldeans in Lebanon are refugees from Iraq. The community follows the Code of Procedure for Tribunals of Eastern Catholic Churches.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2008-001', 'Law 25/2008', 'قانون الانتخابات النيابية', 'Loi sur les élections législatives', 'Parliamentary Elections Law', '2008-10-08', 'Recent Legislation - Electoral Reform', NULL, 'amended', 'Passed after Doha Agreement to break political deadlock. Extended parliamentary mandate twice (2013, 2014). Repealed by Law 44/2017.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2017-002', 'Law 44/2017', 'قانون الانتخابات النيابية - التمثيل النسبي', 'Loi sur les élections législatives - Représentation proportionnelle', 'Parliamentary Elections Law - Proportional Representation', '2017-06-17', 'Recent Legislation - Electoral Reform', NULL, 'active', 'First time Lebanon adopted proportional representation. Passed after years of political deadlock and two mandate extensions. Amended in 2021 regarding diaspora voting procedures.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2000-003', 'Law 220/2000', 'قانون حقوق الأشخاص ذوي الإعاقة', 'Loi sur les droits des personnes handicapées', 'Law on the Rights of Persons with Disabilities', '2000-05-29', 'Recent Legislation - Disability Rights', NULL, 'active', 'Landmark legislation passed six years before UN Convention on Rights of Persons with Disabilities. First comprehensive disability rights law in Lebanon. Implementation remains weak.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2017-004', 'Law 28/2017', 'قانون الحق في الوصول إلى المعلومات', 'Loi sur le droit d''accès à l''information', 'Access to Information Law', '2017-02-10', 'Recent Legislation - Anti-Corruption and Transparency', NULL, 'active', 'First Lebanese law on access to information. Drafted since 2001, passed after civil society advocacy. Amended in 2021 to remove requirement to specify capacity/interest and include religious courts.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2018-005', 'Law 83/2018', 'قانون حماية المبلغين عن الفساد', 'Loi sur la protection des lanceurs d''alerte', 'Whistleblower Protection Law', '2018-10-10', 'Recent Legislation - Anti-Corruption and Transparency', NULL, 'active', 'Passed to fulfill Lebanon''s obligations under UN Convention Against Corruption (ratified 2008). Amended in 2020 to allow Public Prosecution to receive disclosures alongside NACC.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2020-006', 'Law 175/2020', 'قانون مكافحة الفساد في القطاع العام وإنشاء الهيئة الوطنية لمكافحة الفساد', 'Loi sur la lutte contre la corruption dans le secteur public et création de la Commission nationale anti-corruption', 'Anti-Corruption Law and Establishment of National Anti-Corruption Commission', '2020-05-08', 'Recent Legislation - Anti-Corruption and Transparency', NULL, 'active', 'Passed in response to October 2019 uprising against corruption. First comprehensive anti-corruption law defining corruption and establishing dedicated commission. NACC officially launched in December 2022.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2020-007', 'Law 189/2020', 'قانون الإثراء غير المشروع والإفصاح عن الأموال والمصالح', 'Loi sur l''enrichissement illicite et déclaration des biens et intérêts', 'Illicit Enrichment and Assets/Interests Declaration Law', '2020-10-16', 'Recent Legislation - Anti-Corruption and Transparency', NULL, 'active', 'Replaced obsolete 1954 law. Expanded declaration requirements and removed prescription period. Assigned NACC as sole body for receiving declarations (previously 24 different bodies).', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2014-008', 'Law 293/2014', 'قانون حماية النساء وأفراد الأسرة من العنف الأسري', 'Loi sur la protection des femmes et membres de la famille contre la violence domestique', 'Law on Protection of Women and Family Members from Domestic Violence', '2014-05-07', 'Recent Legislation - Women''s Rights and Protection', NULL, 'active', 'First Lebanese law criminalizing domestic violence. Result of years of advocacy by KAFA and women''s organizations. Does not criminalize marital rape. Amended in 2020 to strengthen penalties for economic/psychological violence.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2011-009', 'Law 164/2011', 'قانون معاقبة جريمة الاتجار بالأشخاص', 'Loi sur la répression du crime de traite des personnes', 'Law on Punishment for the Crime of Trafficking in Persons', '2011-08-24', 'Recent Legislation - Human Trafficking and Organized Crime', NULL, 'active', 'Passed following Lebanon''s ratification of UN Convention Against Transnational Organized Crime and its Trafficking Protocol (2005). First specific anti-trafficking legislation in Lebanon.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2010-010', 'Law 132/2010', 'قانون الموارد البترولية البحرية', 'Loi sur les ressources pétrolières offshore', 'Offshore Petroleum Resources Law (OPRL)', '2010-08-24', 'Recent Legislation - Energy and Petroleum', NULL, 'active', 'Established legal framework for offshore oil and gas exploration. Created Lebanese Petroleum Administration as independent regulator. Mandated creation of sovereign wealth fund for petroleum revenues.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2018-011', 'Law 84/2018', 'قانون تعزيز الشفافية في قطاع البترول', 'Loi sur le renforcement de la transparence dans le secteur pétrolier', 'Law on Enhancing Transparency in the Petroleum Sector', '2018-10-18', 'Recent Legislation - Anti-Corruption and Transparency', NULL, 'active', 'First sector-specific transparency law in Lebanon. Made Lebanon first Eastern Mediterranean country to publish oil contracts. Requires disclosure of beneficial ownership - a global benchmark.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2023-012', 'Law 320/2023', 'قانون الصندوق السيادي اللبناني', 'Loi sur le Fonds souverain libanais', 'Lebanese Sovereign Wealth Fund Law', '2023-12-22', 'Recent Legislation - Energy and Petroleum', NULL, 'active', 'Implemented Article 87 of Law 132/2010. Establishes framework for managing future oil and gas revenues. Based on IMF standards and global best practices for sovereign wealth funds.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2021-013', 'Law 244/2021', 'قانون المشتريات العامة في لبنان', 'Loi sur les marchés publics au Liban', 'Public Procurement Law', '2021-07-19', 'Recent Legislation - Public Sector Reform', NULL, 'active', 'First major update to public procurement law since 1960s. Transforms Lebanese procurement system with international standards. Created independent Complaints Authority. Took effect July 2022.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2022-014', 'Law 306/2022', 'قانون تعديل قانون سرية المصارف', 'Loi modifiant la loi sur le secret bancaire', 'Banking Secrecy Law Amendment', '2022-10-28', 'Recent Legislation - Banking Sector Reform', NULL, 'amended', 'First major amendment to 1956 Banking Secrecy Law. Passed under IMF pressure. Removed secrecy for public officials, allowed retroactive access for corruption investigations. Further amended in 2025.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2025-015', 'Law 1/2025', 'قانون تعديل قانون سرية المصارف - التعديل الثاني', 'Loi modifiant la loi sur le secret bancaire - Deuxième amendement', 'Banking Secrecy Law Amendment (Second)', '2025-04-24', 'Recent Legislation - Banking Sector Reform', NULL, 'active', 'Key IMF prior action. Grants unprecedented access to banking information for restructuring and accountability. 10-year retroactivity allows investigation of pre-crisis financial engineering. Passed with 87 votes for, 13 against.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2025-016', 'Law 28/2025', 'قانون إصلاح وإعادة تنظيم المصارف في لبنان', 'Loi sur la réforme et la réorganisation des banques au Liban', 'Bank Reform and Reorganization Law', '2025-07-31', 'Recent Legislation - Banking Sector Reform', NULL, 'active', 'One of three key IMF prior actions. Establishes framework for bank restructuring six years into financial crisis. Gives BdL Governor significant powers. Criticized for banking lobby influence in HBC composition.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2020-017', 'Decree 6198/2020', 'مرسوم إعلان حالة التعبئة العامة لمواجهة انتشار فيروس كورونا', 'Décret déclarant l''état de mobilisation générale pour contrer la propagation du coronavirus', 'Decree Declaring State of General Mobilization to Counter Coronavirus Spread', '2020-03-15', 'Recent Legislation - Healthcare and Pandemic Response', NULL, 'active', 'First COVID-19 response measure. Based on 1957 Infectious Diseases Law and Legislative Decree 102/1983 on National Defense. Imposed strict lockdown measures without parliamentary legislation.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2021-018', 'Law 211/2021', 'قانون تنظيم الاستخدام الطارئ للمنتجات الطبية لمواجهة جائحة كوفيد-19', 'Loi réglementant l''utilisation d''urgence des produits médicaux pour combattre la pandémie COVID-19', 'Law Regulating Emergency Use of Medical Products to Combat COVID-19 Pandemic', '2021-01-16', 'Recent Legislation - Healthcare and Pandemic Response', NULL, 'active', 'Provided legal framework for COVID-19 vaccination campaign. Shielded healthcare providers and manufacturers from liability. Allowed private sector to procure vaccines alongside government.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2002-019', 'Law 444/2002', 'قانون حماية البيئة', 'Loi sur la protection de l''environnement', 'Environmental Protection Law', '2002-07-29', 'Recent Legislation - Environmental and Climate', NULL, 'active', 'Cornerstone of Lebanese environmental legislation. Mandates Environmental Impact Assessments for major projects. Established framework for pollution control and biodiversity protection.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2018-020', 'Law 78/2018', 'قانون جودة الهواء', 'Loi sur la qualité de l''air', 'Air Quality Law', '2018-10-23', 'Recent Legislation - Environmental and Climate', NULL, 'active', 'Complements Law 444/2002. Addresses air pollution from power plants, vehicles, generators. Aligns with Lebanon''s NDC targets for 2030.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2002-021', 'Law 431/2002', 'قانون قطاع الاتصالات', 'Loi sur le secteur des télécommunications', 'Telecommunications Sector Law', '2002-12-18', 'Recent Legislation - Telecommunications and Technology', NULL, 'partially_implemented', 'Passed in anticipation of Paris II donors conference. TRA board expired in 2012 and never reconstituted. Liban Telecom never established. Law remains largely unimplemented after 20+ years.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2025-022', 'Law (Judicial Reform) 2025', 'قانون تنظيم القضاء العادي', 'Loi sur l''organisation du pouvoir judiciaire ordinaire', 'Law Regulating the Ordinary Judiciary', '2025-07-31', 'Recent Legislation - Judicial Reform', NULL, 'active', 'First major judicial reform since independence. Based on draft from 2018 by coalition of legal NGOs. Criticized by HRW and Venice Commission for not fully meeting international standards. Enters force January 2026.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2000-023', 'Labor Law Amendment 2000', 'تعديل المادة 26 من قانون العمل - عدم التمييز بين الرجل والمرأة', 'Amendement Article 26 Code du travail - non-discrimination homme-femme', 'Labor Law Article 26 Amendment - Gender Non-Discrimination', '2000-05-26', 'Recent Legislation - Women''s Rights and Protection', NULL, 'active', 'First amendment prohibiting gender discrimination in Labor Law. However, Article 27 restrictions on women''s work in certain industries remained. Maternity leave extended to 60 days (public sector) and 7 weeks (private sector).', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2025-024', 'Law 22/2025', 'قانون تعديل قانون العمل - الاعتراف بالعمل عن بُعد وغير التقليدي', 'Loi modifiant le Code du travail - reconnaissance travail à distance et non traditionnel', 'Labor Law Amendment - Recognition of Remote and Non-Traditional Work', '2025-05-16', 'Recent Legislation - Labor and Employment', NULL, 'active', 'First major labor law reform in decades. Recognizes remote work, part-time employment, compressed schedules, and seasonal work. Brings Lebanese labor law closer to international standards.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2021-025', 'Law 189/2021', 'قانون المنافسة', 'Loi sur la concurrence', 'Competition Law', '2021-12-21', 'Recent Legislation - Economic Reform', NULL, 'active', 'First comprehensive competition law in Lebanon. Establishes National Competition Authority (not yet created). Addresses cartels, abuse of dominance, and merger control. Critical for economic recovery and reducing inequality.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2019-026', 'Informal Capital Controls (No Law)', 'الضوابط الرأسمالية غير الرسمية - لا قانون رسمي', 'Contrôles de capitaux informels - aucune loi formelle', 'Informal Capital Controls - No Formal Law', '2019-10-18', 'Recent Legislation - Capital Controls and Banking Restrictions', NULL, 'active', 'Banks imposed informal capital controls on October 18, 2019 following bank run. No parliamentary legislation passed despite IMF requirements. Multiple draft laws debated but never enacted as of April 2025.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2020-027', 'National Anti-Corruption Strategy 2020-2025', 'الاستراتيجية الوطنية لمكافحة الفساد 2020-2025', 'Stratégie nationale de lutte contre la corruption 2020-2025', 'National Anti-Corruption Strategy 2020-2025', '2020-05-01', 'Recent Legislation - Anti-Corruption and Transparency', NULL, 'active', 'Comprehensive roadmap for anti-corruption efforts. Developed with UNDP/UNODC support. Approved by Ministerial Anti-Corruption Committee. Implementation remains limited due to political and economic crises.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2025-028', 'Draft Financial Gap Law 2025', 'مشروع قانون سد الفجوة المالية - مسودة', 'Projet de loi sur le comblement de l''écart financier - ébauche', 'Draft Financial Gap Law (Gap Law)', '2025-12-27', 'Recent Legislation - Economic and Financial Crisis', NULL, 'pending', 'Third key IMF prior action. Cabinet approved December 27, 2025. Parliament approval pending. Determines loss-sharing between state, BdL, banks, and depositors for $70 billion gap. Hotly debated with banking lobby opposition.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2002-029', 'Law 462/2002', 'قانون تنظيم قطاع الكهرباء', 'Loi sur la régulation du secteur de l''électricité', 'Electricity Sector Regulation Law', '2002-09-02', 'Recent Legislation - Energy and Infrastructure', NULL, 'partially_implemented', 'Passed before Paris II conference. Electricity Regulatory Authority never established. Law remains largely unimplemented. Electricité du Liban (EdL) continues as state monopoly with massive deficits.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2017-030', 'Decree 167/2017', 'مرسوم الحوافز الضريبية على المنتجات والخدمات البيئية', 'Décret incitations fiscales produits et services environnementaux', 'Tax Incentives on Environmental Products and Services Decree', '2017-03-15', 'Recent Legislation - Environmental and Climate', NULL, 'active', 'Part of Lebanon''s climate mitigation strategy. Encourages deployment of climate-friendly technologies. Complements vehicle tax reductions for hybrid/electric cars in budget laws.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2022-031', 'MoE Decision 16/1/2022', 'قرار حدود انبعاث الملوثات الهوائية', 'Décision limites émission polluants atmosphériques', 'Emission Limit Values for Air Pollutants Decision', '2022-01-16', 'Recent Legislation - Environmental and Climate', NULL, 'active', 'Implements Lebanon''s NDC commitments. Limits emissions from major pollution sources. Addresses severe air quality problems in Lebanon, especially from private generators during electricity crisis.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2008-032', 'Law 33/2008', 'قانون الموافقة على انضمام لبنان إلى اتفاقية الأمم المتحدة لمكافحة الفساد', 'Loi approuvant adhésion Liban à Convention ONU contre corruption', 'Law Approving Lebanon''s Accession to UN Convention Against Corruption (UNCAC)', '2008-10-16', 'Recent Legislation - International Treaty Ratifications', NULL, 'active', 'Lebanon ratified UNCAC in 2008. Led to subsequent anti-corruption legislation including Whistleblower Protection Law (2018), Access to Information Law (2017), and National Anti-Corruption Commission Law (2020).', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2022-033', 'Law (Ratification) 2022', 'قانون التصديق على اتفاقية حقوق الأشخاص ذوي الإعاقة وملحقها الاختياري', 'Loi ratifiant Convention droits personnes handicapées et Protocole facultatif', 'Law Ratifying Convention on Rights of Persons with Disabilities and Optional Protocol', '2022-04-15', 'Recent Legislation - International Treaty Ratifications', NULL, 'active', 'Lebanon signed CRPD in 2007 but ratification took 15 years. Law 220/2000 (Disability Rights) preceded the UN Convention. Ratification strengthens legal framework for disability rights in Lebanon.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2020-034', 'Law 204/2020', 'قانون تعديل قانون حماية النساء من العنف الأسري', 'Loi modifiant loi protection femmes contre violence domestique', 'Amendment to Domestic Violence Protection Law', '2020-09-21', 'Recent Legislation - Women''s Rights and Protection', NULL, 'active', 'Amended Law 293/2014 to address gaps identified in implementation. Strengthened penalties for non-physical forms of violence. Still does not criminalize marital rape.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2021-035', 'Law 233/2021', 'قانون تعديل قانون الحق في الوصول إلى المعلومات', 'Loi modifiant loi droit accès à l''information', 'Amendment to Access to Information Law', '2021-07-19', 'Recent Legislation - Anti-Corruption and Transparency', NULL, 'active', 'Strengthened Law 28/2017 based on civil society advocacy. Removed barriers to accessing information. Included religious courts previously exempted.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2021-036', 'Law 214/2021', 'قانون استرداد الأموال الناتجة عن جرائم الفساد', 'Loi sur récupération fonds provenant crimes corruption', 'Asset Recovery Law', '2021-12-15', 'Recent Legislation - Anti-Corruption and Transparency', NULL, 'active', 'Complements Law 175/2020 and Law 189/2020. Implements UNCAC provisions on asset recovery. Provides framework for recovering stolen assets from abroad.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2020-037', 'Law 182/2020', 'قانون تعديل قانون حماية المبلغين عن الفساد', 'Loi modifiant loi protection lanceurs d''alerte', 'Amendment to Whistleblower Protection Law', '2020-06-12', 'Recent Legislation - Anti-Corruption and Transparency', NULL, 'active', 'Amended Law 83/2018 to allow Public Prosecution to receive whistleblower complaints alongside NACC. Created Whistleblowers Reception Office at Ministry of Justice.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-1977-038', 'Legislative Decree 118/1977', 'المرسوم الاشتراعي رقم 118 قانون البلديات', 'Décret-loi No. 118 Code des municipalités', 'Municipalities Law', '1977-06-30', 'Recent Legislation - Electoral Reform', NULL, 'active', 'Passed at end of 1975-1977 civil war. Municipal elections still use majoritarian system (Law 25/2008) unlike parliamentary elections which use proportional representation (Law 44/2017). Proposed reforms in 2023 would introduce proportional representation for municipal elections.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2013-039', 'MoE Decision 99/1/2013', 'قرار آلية الإبلاغ عن الكربون', 'Décision mécanisme rapport carbone', 'Carbon Reporting Mechanism Decision', '2013-03-15', 'Recent Legislation - Environmental and Climate', NULL, 'active', 'Early climate action measure. Voluntary carbon reporting for private sector. Part of Lebanon''s climate mitigation strategy and NDC implementation.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2018-040', 'Budget Law 79/2018 Article 55', 'قانون الموازنة 79/2018 - المادة 55 - تخفيض ضريبة المركبات الهجينة والكهربائية', 'Loi budget 79/2018 Article 55 - réduction taxe véhicules hybrides et électriques', 'Budget Law 79/2018 Article 55 - Vehicle Tax Reduction for Hybrid/Electric Vehicles', '2018-04-20', 'Recent Legislation - Environmental and Climate', NULL, 'active', 'Incentivizes low-emission vehicles. Maintained through 2019-2022 despite economic crisis. Extended by Budget Law 10/2022.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-2007-041', 'Law (Ratification) 2007', 'قانون التصديق على اتفاقية نيويورك 1958', 'Loi ratifiant Convention New York 1958', 'Law Ratifying New York Convention 1958', '2007-07-11', 'Recent Legislation - International Treaty Ratifications', NULL, 'active', 'Lebanon ratified New York Convention on Recognition and Enforcement of Foreign Arbitral Awards. Important for international trade and investment disputes.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-ICSID', 'ICSID Convention Member', 'عضوية لبنان في اتفاقية ICSID', 'Membre Liban Convention ICSID', 'Lebanon ICSID Convention Member', '1971-04-15', 'Recent Legislation - International Treaty Ratifications', NULL, 'active', 'Lebanon member of ICSID Convention since 1971. Government accepts international arbitration for investment disputes, especially with countries having investment protection agreements.', NULL) ON CONFLICT (law_id) DO NOTHING;
