INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-REC-020', 'Law No. 306/2022', NULL, NULL, NULL, NULL, 'Banking & Financial', NULL, 'active', NULL, NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-TAX-001', 'Decree-Law No. 144 of June 12, 1959 (Income Tax)', 'مرسوم اشتراعي رقم 144/1959 - ضريبة الدخل', 'Décret-loi No. 144/1959 - Impôt sur le Revenu', 'Income Tax Law', '1959-06-12', 'Tax & Fiscal', 'Income Tax', 'amended', 'Lebanon''s income tax system is a schedular (cedular) system where different types of income are taxed separately rather than aggregated. There is no unified personal income tax. Tax rates are relatively low compared to regional and international averages, reflecting Lebanon''s traditionally liberal economic model. The system has been criticized for its regressive nature and weak enforcement.', 80) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-TAX-002', 'Law No. 379 of December 14, 2001 (VAT)', 'قانون الضريبة على القيمة المضافة - قانون رقم 379/2001', 'Loi No. 379/2001 - Taxe sur la Valeur Ajoutée (TVA)', 'Value Added Tax (VAT) Law', '2001-12-14', 'Tax & Fiscal', 'VAT', 'amended', 'Introduced in 2002 at a rate of 10%, later increased to 11%. Replaced the consumption tax system. Registration threshold applies for businesses with turnover above a set threshold. Exemptions include financial services, education, and certain basic food items. Administration by the VAT Directorate within the Ministry of Finance.', 63) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-TAX-003', 'Legislative Decree of October 31, 1967 (Stamp Duty)', 'قانون الطوابع المالية', 'Loi sur le Timbre Fiscal', 'Stamp Duty / Fiscal Stamps Law', '1967-10-31', 'Tax & Fiscal', 'Stamp Duty', 'amended', 'Imposes stamp duty on various legal documents, contracts, receipts, and official papers. Rates vary by document type. A significant source of government revenue and a common feature of Lebanese administrative processes.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-TAX-004', 'Customs Code (Various decrees, consolidated)', 'قانون الجمارك', 'Code des Douanes', 'Customs Code', '2000-09-06', 'Tax & Fiscal', 'Customs', 'amended', 'Governs customs duties, import/export procedures, transit goods, customs zones, and enforcement. Lebanon has been in accession negotiations with the WTO and has bilateral trade agreements affecting customs rates. Customs revenue has historically been a major source of government income.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-TAX-005', 'Law No. 44 of November 14, 2008 (Tax Procedures)', 'قانون الإجراءات الضريبية - قانون رقم 44/2008', 'Loi No. 44/2008 - Procédures Fiscales', 'Tax Procedures Law (Unified)', '2008-11-14', 'Tax & Fiscal', 'Tax Administration', 'active', 'Unified and simplified tax procedures across income tax, VAT, and other fiscal obligations. Implementing decree No. 2488 of July 3, 2009. Streamlined tax filing, assessment, objection, and collection procedures.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-TAX-006', 'Built Property Tax (Decree-Law No. 148/1959)', 'ضريبة الأملاك المبنية - مرسوم اشتراعي رقم 148/1959', 'Impôt Foncier sur les Propriétés Bâties', 'Built Property Tax', '1959-06-12', 'Tax & Fiscal', 'Property Tax', 'amended', 'Taxes on built property (buildings and structures). Calculated based on estimated rental value. One of the oldest existing tax instruments in Lebanon.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-TAX-007', 'Law No. 43 of November 24, 2015 (Exchange of Tax Information)', 'قانون تبادل المعلومات الضريبية - قانون رقم 43/2015', 'Loi No. 43/2015 - Échange de Renseignements Fiscaux', 'Exchange of Tax Information Law', '2015-11-24', 'Tax & Fiscal', 'International Tax Cooperation', 'active', 'Enacted to comply with international standards on tax transparency (OECD/Global Forum). Allows exchange of tax-related information with treaty partner countries. Significant in the context of Lebanon''s banking secrecy tradition.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LB-TAX-008', 'Annual Budget Laws (various)', 'قوانين الموازنة العامة', 'Lois de Finances', 'Annual Budget Laws', '1920-01-01', 'Tax & Fiscal', 'Budget', 'active', 'Annual budget laws authorize government spending and often contain tax rate modifications. Lebanon notably failed to pass a budget from 2005 to 2017 (12 years), operating on extended twelve-monthly budgets. A budget was finally passed in 2017 (Law No. 64/2017), followed by the 2018 and 2019 budgets. Budget laws often include fiscal provisions that amend tax rates and thresholds.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-001', 'Decree-Law No. 144/1959', 'قانون ضريبة الدخل', 'Décret-Loi sur l''Impôt sur le Revenu', 'Income Tax Law', '1959-06-12', 'Tax Law', 'Income Tax', 'active', 'The Income Tax Law of 1959 is the foundational legislation for taxation in Lebanon. It established the territorial principle of taxation and the schedular system (three categories of income). The law has undergone numerous amendments, particularly in recent years (2017, 2019, 2022, 2024) to adapt to economic changes and increase revenue collection.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-002', 'Law No. 379/2001', 'قانون ضريبة القيمة المضافة', 'Loi sur la Taxe sur la Valeur Ajoutée', 'Value Added Tax Law', '2001-12-14', 'Tax Law', 'VAT', 'active', 'VAT was introduced in Lebanon on 1 February 2002, replacing the previous turnover tax system. The law was designed to modernize the tax system and broaden the tax base. The standard rate of 11% is relatively low compared to international standards.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-003', 'Decree No. 283/1959', 'مرسوم ضريبة الأملاك المبنية', 'Décret sur la Taxe des Propriétés Bâties', 'Built Property Tax Decree', '1959', 'Tax Law', 'Property Tax', 'active', 'The Built Property Tax is one of Lebanon''s oldest property taxes, applying to rental income from built properties. The progressive rate structure aims to tax higher rental incomes at higher rates.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-004', 'Legislative Decree No. 146/1959', 'المرسوم التشريعي رقم 146 المتعلق بتحديد الضرائب المستوجبة على الهبات والإرث', 'Décret Législatif No. 146 déterminant les taxes applicables aux donations et successions', 'Legislative Decree on Inheritance and Gift Tax', '1959-06-12', 'Tax Law', 'Inheritance and Gift Tax', 'active', 'The Inheritance and Gift Tax Law of 1959 establishes the framework for taxing transfers of wealth upon death or by gift. The tax applies based on both territoriality and residence principles. The progressive rate structure favors close family members with lower rates.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-005', 'Customs Law (Consolidated)', 'قانون الجمارك', 'Loi des Douanes', 'Customs Law', 'Various dates - consolidated legislation', 'Tax Law', 'Customs and Import Duties', 'active', 'Lebanon''s Customs Law governs import and export duties. The law establishes the Higher Council of Customs which sets tariff rates. Lebanon applies the Harmonized System for tariff classification.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-006', 'Stamp Duty Law (Various Provisions)', 'قانون الطابع المالي', 'Loi sur le Timbre Fiscal', 'Stamp Duty Law', 'Original law with multiple amendments', 'Tax Law', 'Stamp Duty', 'active', 'Stamp duty is one of Lebanon''s oldest taxes, applying to various documents and transactions. The law distinguishes between proportionate and fixed stamp duties.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-007', 'Law No. 296/2001 and Law No. 360', 'قانون تسجيل العقارات ورسوم التحويل', 'Loi sur l''Enregistrement des Biens Immobiliers et les Droits de Mutation', 'Real Estate Registration and Transfer Tax Law', '2001-03-20 (Law 296), 2001-08-16 (Law 360)', 'Tax Law', 'Real Estate Transfer Tax', 'active', 'Law 296/2001 was a major reform to encourage foreign real estate investment by simplifying ownership rules and reducing fees. Law 360/2001 further liberalized foreign acquisition limits. The 2018 amendment provided temporary reductions for residential properties.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-008', 'Various Provisions in Budget Laws', 'الضرائب الانتقائية', 'Taxes d''Accise', 'Excise Taxes', 'Various dates - provisions in annual Budget Laws', 'Tax Law', 'Excise Tax', 'active', 'Excise taxes in Lebanon are primarily applied to ''sin goods'' and luxury items. Rates are adjusted annually through Budget Laws.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-009', 'Decree-Law No. 144/1959 (Withholding Tax Provisions)', 'أحكام الضريبة المقتطعة', 'Dispositions sur la Retenue à la Source', 'Withholding Tax Regulations', '1959-06-12 (with amendments)', 'Tax Law', 'Withholding Tax', 'active', 'Withholding taxes are a key mechanism for revenue collection in Lebanon. The 2024 amendments increased non-resident WHT rates significantly to boost revenue.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-010', 'Tax Procedures Law (Various Provisions)', 'قانون أصول المحاسبة والمراقبة الضريبية', 'Loi sur les Procédures Fiscales et le Contrôle', 'Tax Procedures and Control Law', 'Various dates - consolidated provisions', 'Tax Law', 'Tax Procedures', 'active', 'Tax procedures in Lebanon are governed by various provisions scattered across tax laws. Recent reforms have focused on electronic filing and streamlining compliance.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-011', 'Various Amnesty Laws', 'قوانين العفو والتسوية الضريبية', 'Lois d''Amnistie et de Règlement Fiscal', 'Tax Amnesty and Settlement Laws', 'Various dates', 'Tax Law', 'Tax Amnesty', 'varies_by_law', 'Lebanon has periodically enacted tax amnesty laws to encourage compliance and increase revenue collection. These laws typically offer reduced penalties and interest for taxpayers who voluntarily disclose and pay outstanding taxes.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-012', 'Multiple DTT Agreements', 'اتفاقيات منع الازدواج الضريبي', 'Conventions de Double Imposition', 'Double Taxation Treaties', 'Various dates', 'Tax Law', 'International Taxation', 'active', 'Lebanon has concluded over 30 double taxation treaties to promote international trade and investment. These treaties generally follow the OECD model and reduce withholding tax rates on cross-border payments.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-013', 'Decree-Law No. 45/1983', 'قانون الشركات القابضة', 'Décret-Loi sur les Sociétés de Participations', 'Holding Companies Law', '1983', 'Tax Law', 'Special Company Regimes', 'active', 'The Holding Companies Law was enacted in 1983 to encourage investment and regional headquarters in Lebanon. It provides significant tax exemptions to companies whose main activity is owning shares in other companies.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-014', 'Decree-Law No. 46/1983', 'قانون الشركات الخارجية', 'Décret-Loi sur les Sociétés Offshore', 'Offshore Companies Law', '1983', 'Tax Law', 'Special Company Regimes', 'active', 'The Offshore Companies Law was enacted alongside the Holding Companies Law in 1983 to attract international business to Lebanon. Offshore companies benefit from significant tax exemptions but are restricted to activities outside Lebanon.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-015', 'Part of Decree-Law No. 144/1959 (as amended)', 'أحكام ضريبة الأرباح الرأسمالية', 'Dispositions sur l''Impôt sur les Plus-Values', 'Capital Gains Tax Provisions', '1959-06-12 (with amendments)', 'Tax Law', 'Capital Gains Tax', 'active', 'Capital gains taxation in Lebanon varies by asset type. The 2024 amendments introduced temporary reductions for real estate to stimulate the market.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-016', 'National Social Security Fund Law', 'قانون الضمان الاجتماعي', 'Loi sur la Sécurité Sociale', 'Social Security Law', 'Various dates', 'Tax Law', 'Social Security Contributions', 'active', 'Social security contributions are separate from but related to the tax system. They fund maternity/sickness benefits, family allowances, and end-of-service indemnities.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-017', 'Law No. 324/2024', 'قانون الموازنة العامة لعام 2024', 'Loi de Finances pour l''année 2024', 'General Budget Law for 2024', '2024-02-12', 'Tax Law', 'Budget Law', 'active', 'The 2024 Budget Law introduced significant tax amendments to increase revenue collection, particularly targeting non-resident withholding taxes and stamp duties.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-018', 'Budget Law 2025 (Draft/Pending)', 'مشروع قانون موازنة 2025', 'Projet de Loi de Finances 2025', 'Budget Law 2025 (Draft)', '2025 (expected)', 'Tax Law', 'Budget Law', 'pending', 'The 2025 Budget was submitted to government in September 2024 with a projected deficit. It introduces new fees and modifies tax calculation methods for foreign currency salaries.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-019', 'Part of Decree-Law No. 144/1959', 'أحكام طريقة الربح المفترض', 'Dispositions sur la Méthode du Bénéfice Forfaitaire', 'Deemed Profit Method Provisions', '1959-06-12', 'Tax Law', 'Tax Calculation Methods', 'active (transitioning)', 'The deemed profit method was introduced for specific industries where actual profit calculation is difficult. The 2025 notification mandates transition to the lump-sum method starting 2026.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-020', 'Various Municipal Tax Laws', 'الضرائب البلدية', 'Taxes Municipales', 'Municipal Tax Provisions', 'Various dates', 'Tax Law', 'Municipal Tax', 'active', 'Municipal taxes are levied by local authorities and include taxes on rental income and fees on real estate transfers.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-021', 'Law No. 44/2016', 'قانون تحديد الإقامة الضريبية في لبنان', 'Loi définissant la Résidence Fiscale au Liban', 'Tax Residency Definition Law', '2016', 'Tax Law', 'Tax Residency', 'active', 'Law No. 44/2016 expanded the definition of tax residency in Lebanon, adding the 183-day rule and the habitual abode criterion to align with international standards.', NULL) ON CONFLICT (law_id) DO NOTHING;
INSERT INTO laws (law_id, official_number, title_ar, title_fr, title_en, date_enacted, category, subcategory, status, historical_context, total_articles) VALUES ('LBN-TAX-022', 'Law No. 64/2017', 'قانون رقم 64 المتعلق بضريبة الفوائد', 'Loi No. 64 sur l''Impôt sur les Intérêts', 'Interest Tax Law', '2017-10-26', 'Tax Law', 'Interest Taxation', 'active', 'Law No. 64/2017 increased the tax on interest revenue to 7%, replacing previous rates. This is a final withholding tax that cannot be refunded or credited.', NULL) ON CONFLICT (law_id) DO NOTHING;
