-- Case Map: Lebanese Legal Database Import
-- Generated: March 11, 2026
-- Laws: 289, Chunks: 3361

-- 1. Create tables

CREATE TABLE IF NOT EXISTS laws (
  id SERIAL PRIMARY KEY,
  law_id TEXT NOT NULL UNIQUE,
  official_number TEXT,
  title_ar TEXT,
  title_fr TEXT,
  title_en TEXT,
  date_enacted TEXT,
  category TEXT,
  subcategory TEXT,
  status TEXT,
  historical_context TEXT,
  total_articles INTEGER
);

CREATE TABLE IF NOT EXISTS chunks (
  id SERIAL PRIMARY KEY,
  law_id TEXT NOT NULL,
  article_number TEXT,
  chunk_text TEXT NOT NULL,
  language TEXT,
  citation_label TEXT NOT NULL,
  subject TEXT,
  category TEXT
);

CREATE TABLE IF NOT EXISTS profiles (
  id SERIAL PRIMARY KEY,
  visitor_id TEXT NOT NULL UNIQUE,
  free_questions_remaining INTEGER NOT NULL DEFAULT 1,
  subscription_status TEXT NOT NULL DEFAULT 'inactive',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS queries (
  id SERIAL PRIMARY KEY,
  visitor_id TEXT NOT NULL,
  question TEXT NOT NULL,
  answer_markdown TEXT,
  citations_json JSONB,
  sources_json JSONB,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Enable RLS
ALTER TABLE laws ENABLE ROW LEVEL SECURITY;
ALTER TABLE chunks ENABLE ROW LEVEL SECURITY;
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE queries ENABLE ROW LEVEL SECURITY;

-- 3. Create read-only policies (laws and chunks are public read)
CREATE POLICY "Allow public read on laws" ON laws FOR SELECT USING (true);
CREATE POLICY "Allow public read on chunks" ON chunks FOR SELECT USING (true);
CREATE POLICY "Allow public read on profiles" ON profiles FOR SELECT USING (true);
CREATE POLICY "Allow public insert on profiles" ON profiles FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow public update on profiles" ON profiles FOR UPDATE USING (true);
CREATE POLICY "Allow public read on queries" ON queries FOR SELECT USING (true);
CREATE POLICY "Allow public insert on queries" ON queries FOR INSERT WITH CHECK (true);

-- 4. Create search index
CREATE INDEX IF NOT EXISTS idx_chunks_law_id ON chunks(law_id);
CREATE INDEX IF NOT EXISTS idx_chunks_category ON chunks(category);
CREATE INDEX IF NOT EXISTS idx_chunks_language ON chunks(language);
CREATE INDEX IF NOT EXISTS idx_chunks_text_search ON chunks USING gin(to_tsvector('english', chunk_text));

